    document.addEventListener("click", function (e) {

        if (!e.target.classList.contains("alert-menu-btn")) {
            document.querySelectorAll(".custom-action-menu").forEach(function (m) {
                m.remove();
            });
        }

        if (e.target.classList.contains("alert-menu-btn")) {
            e.stopPropagation();
            var id = e.target.getAttribute("data-id");
            openActionMenu(e.target, id);
        }
    });
    
    function loadRoleTypes() {

        fetch("\${pageContext.request.contextPath}/sck360/getAllRoles", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ uniqueId: uniqueId })
        })
        .then(res => res.json())
        .then(function(resp){

            var select = document.getElementById("user_role_type");

            // prevent reloading again and again
            if (select.getAttribute("data-loaded") === "true") return;

            select.innerHTML = "<option value=''>Select Role Type</option>";

            (resp.data || []).forEach(function(role){
                select.innerHTML +=
                    "<option value='" + escAttr(role.roleName) + "'>" + escapeHtml(role.roleName) + "</option>";
            });

            select.setAttribute("data-loaded", "true");
        });
    }
    
    document.addEventListener("focusin", function(e){

        if (e.target && e.target.id === "user_role_type") {
            loadRoleTypes();
        }
    });

    function openActionMenu(btn, id) {

        document.querySelectorAll(".custom-action-menu")
            .forEach(m => m.remove());

        var menu = document.createElement("div");
        menu.className = "custom-action-menu";

        if (activeTab === "departments") {

            addMenuBtn(menu, "Edit", () => openDeptUpdate(id));
            addMenuBtn(menu, "Delete", () => deleteDepartment(id));
        }

        if (activeTab === "categories") {

            addMenuBtn(menu, "Edit", () => openCategoryUpdate(id));
            addMenuBtn(menu, "Delete", () => deleteCategory(id));
        }

        if (activeTab === "users") {

            addMenuBtn(menu, "Edit", () => openUserUpdate(id));
            addMenuBtn(menu, "Delete", () => deleteUser(id));
        }
        
        if (activeTab === "modules") {
            addMenuBtn(menu, "Edit", () => openModuleUpdate(id));
            addMenuBtn(menu, "Delete", () => deleteModule(id));
        }

        document.body.appendChild(menu);

        var rect = btn.getBoundingClientRect();
        menu.style.top = (rect.bottom + window.scrollY) + "px";
        menu.style.left = (rect.left + window.scrollX - 90) + "px";
    }
    
    function sortUsersByDept() {

        allUsers.sort((a,b) => {
            var d1 = allDepartments.find(d => d.id == a.departmentId)?.name || "";
            var d2 = allDepartments.find(d => d.id == b.departmentId)?.name || "";
            return d1.localeCompare(d2);
        });

        renderUsers();
    }
    
