				/* Called by the Apply button */
				function applyDateRange() {
				    var s = document.getElementById("startDateInput").value;
				    var e = document.getElementById("endDateInput").value;
				
				    if (!s || !e) {
				        alert("Please select both start and end dates.");
				        return;
				    }
				
				    var startDate = new Date(s);
				    var maxEnd    = new Date(startDate);
				    maxEnd.setMonth(maxEnd.getMonth() + 1);
				    maxEnd.setDate(maxEnd.getDate() - 1);
				
				    if (new Date(e) > maxEnd) {
				        document.getElementById("dateRangeError").style.display = "inline";
				        return;
				    }
				
				    loadTaskLogs(s, e);
				}
				
