/* ══════════════════════════════════════════
   BREAKDOWN MODAL — By Module / By Client.
   Each row expands in place to show the individual tasks behind it,
   filtered client-side out of taskRecords (already fetched for this range).
══════════════════════════════════════════ */
var breakdownType = null;
var breakdownRows = [];

function openBreakdownModal(type) {
    breakdownType = type;
    breakdownRows = type === 'module' ? (D.byModule || []) : (D.byClient || []);

    var title, headHtml, colspan;
    if (type === 'module') {
        title = 'By Module — Full Breakdown';
        colspan = 5;
        headHtml = '<th>Module</th><th style="text-align:center">Logs</th><th style="text-align:center">Total Time</th>' +
            '<th style="text-align:center">Avg / Log</th><th style="text-align:right">% of Total</th>';
    } else {
        title = 'By Client — Full Breakdown';
        colspan = 5;
        headHtml = '<th>#</th><th>Client</th><th style="text-align:center">Logs</th>' +
            '<th style="text-align:center">Duration</th><th style="text-align:right">Share</th>';
    }

    document.getElementById('bdModalTitle').textContent = title;

    var html = '<table class="bd-table"><thead><tr>'+headHtml+'</tr></thead><tbody>';
    breakdownRows.forEach(function(r, i) {
        html += buildBreakdownRow(type, r, i);
        html += '<tr class="bd-detail-row" id="bdDetail'+i+'" style="display:none;"><td colspan="'+colspan+'"><div id="bdDetailBody'+i+'"></div></td></tr>';
    });
    html += '</tbody></table>';
    if (!breakdownRows.length) html = '<div class="wd-empty">No data in range</div>';

    document.getElementById('bdModalBody').innerHTML = html;
    document.getElementById('breakdownModal').classList.add('open');
}

function closeBreakdownModal() { document.getElementById('breakdownModal').classList.remove('open'); }
document.getElementById('breakdownModal').addEventListener('click', function(e){
    if (e.target === this) closeBreakdownModal();
});

function buildBreakdownRow(type, r, i) {
    if (type === 'module') {
        var avg = r.logCount ? Math.round(r.totalMinutes / r.logCount) : 0;
        return '<tr class="bd-row" onclick="toggleBreakdownRow('+i+')">' +
            '<td><i class="fa fa-chevron-right bd-caret" id="bdCaret'+i+'"></i>'+escapeHtml(r.module)+'</td>' +
            '<td style="text-align:center;font-weight:600">'+r.logCount+'</td>' +
            '<td style="text-align:center">'+r.totalFormatted+'</td>' +
            '<td style="text-align:center;color:var(--text-sec)">'+fmt(avg)+'</td>' +
            '<td style="text-align:right;font-weight:700;color:var(--green)">'+r.percentOfTotal+'%</td></tr>';
    }
    return '<tr class="bd-row" onclick="toggleBreakdownRow('+i+')">' +
        '<td style="color:var(--text-muted)">'+(i+1)+'</td>' +
        '<td><i class="fa fa-chevron-right bd-caret" id="bdCaret'+i+'"></i>'+escapeHtml(r.client)+'</td>' +
        '<td style="text-align:center">'+r.logCount+'</td>' +
        '<td style="text-align:center">'+r.totalFormatted+'</td>' +
        '<td style="text-align:right;font-weight:700;color:var(--green)">'+r.percentOfTotal+'%</td></tr>';
}

function toggleBreakdownRow(i) {
    var detailRow = document.getElementById('bdDetail'+i);
    var caret = document.getElementById('bdCaret'+i);
    var isOpen = detailRow.style.display !== 'none';

    if (isOpen) {
        detailRow.style.display = 'none';
        caret.style.transform = '';
        return;
    }
    detailRow.style.display = 'table-row';
    caret.style.transform = 'rotate(90deg)';

    var r = breakdownRows[i];
    var matched = taskRecords.filter(function(t) {
        return breakdownType === 'module' ? t.module === r.module : t.client === r.client;
    });
    matched.sort(function(a, b) { return (b.loggedMinutes||0) - (a.loggedMinutes||0); });

    document.getElementById('bdDetailBody'+i).innerHTML = renderTaskDetailList(matched);
}

function renderTaskDetailList(list) {
    if (!list.length) return '<div class="wd-empty">No matching tasks found</div>';
    var html = '<div class="bd-activity-list">';
    list.forEach(function(t) {
        html += '<div class="bd-activity-item">' +
            '<div class="bd-activity-top">' +
                '<span class="bd-activity-date">'+escapeHtml(t.taskID)+'</span>' +
                '<span style="font-size:12px;font-weight:600">'+escapeHtml(safe(t.taskname))+'</span>' +
                '<span class="bd-activity-dur">'+safe(t.loggedDurationFormatted)+'</span>' +
            '</div>' +
            '<div class="bd-activity-mid">' +
                '<span class="status-pill '+statusPillClass(t.taskStatus)+'">'+escapeHtml(safe(t.taskStatus))+'</span>' +
                '<span class="priority-pill '+priorityPillClass(t.priority)+'">'+escapeHtml(safe(t.priority))+'</span>' +
                (t.targetDate ? '<span class="chip" style="background:#f1f5f9;color:#475569">Target: '+t.targetDate+'</span>' : '') +
            '</div>' +
        '</div>';
    });
    html += '</div>';
    return html;
}

