	function resolveDepartment(cb) {
	  var uniqueId = sessionStorage.getItem("uniqueId");
	  var deptId   = sessionStorage.getItem("departmentId");
	  var selfId   = sessionStorage.getItem("userId");

	  function showUnavailable() {
	    document.getElementById('pageHeadActions').style.display = 'none';
	    document.getElementById('mainCard').style.display = 'none';
	    document.getElementById('noDeptCard').style.display = 'block';
	    cb(false);
	  }

	  /* Step 2 (fallback): resolve the viewer's own department, same as before the grant list existed. */
	  function resolveOwnDepartment() {
	    if (!uniqueId || !deptId) { showUnavailable(); return; }

	    fetch(SCK + "/getAllDepartments", {
	      method:  "POST",
	      headers: { "Content-Type": "application/json" },
	      body:    JSON.stringify({ uniqueId: uniqueId })
	    })
	    .then(function(r) { return r.json(); })
	    .then(function(res) {
	      var depts = (res && res.status === 200 && Array.isArray(res.data)) ? res.data : [];
	      var mine  = depts.find(function(d) { return String(d.id) === String(deptId); });
	      var key   = mine ? DEPT_NAME_TO_KEY[mine.name] : null;
	      if (!key) { showUnavailable(); return; }
	      applyDeptConfig(key);
	      cb(true);
	    })
	    .catch(function(err) { console.warn("Failed to resolve department:", err); showUnavailable(); });
	  }

	  /* Step 1: is this viewer on the "view all" grant list, regardless of their own department? */
	  if (!uniqueId || !selfId) { resolveOwnDepartment(); return; }

	  fetch(CTX + "/dailyActivity/getViewAllUsers", {
	    method:  "POST",
	    headers: { "Content-Type": "application/json" },
	    body:    JSON.stringify({ uniqueId: uniqueId })
	  })
	  .then(function(r) { return r.json(); })
	  .then(function(res) {
	    var granted = (res && res.status === 200 && Array.isArray(res.data)) ? res.data : [];
	    var isGranted = granted.some(function(id) { return String(id) === String(selfId); });

	    if (!isGranted) { resolveOwnDepartment(); return; }

	    VIEW_ALL_MODE = true;
	    loadAllDeptUsersForViewAll();
	    cb(true);
	  })
	  .catch(function(err) { console.warn("Failed to check view-all access:", err); resolveOwnDepartment(); });
	}

	/** VIEW_ALL_MODE only: builds the cross-department user switcher out of all three
	 *  departments' rosters combined, each entry tagged with which DEPT_CONFIG key it belongs
	 *  to so selectUser() can point list/summary/export calls at the right table. */
	function loadAllDeptUsersForViewAll() {
	  var uniqueId = sessionStorage.getItem("uniqueId");
	  var depts = [
	    { name: "Sales",               key: "SALES" },
	    { name: "Implementation",      key: "IMPLEMENTATION" },
	    { name: "Product & Marketing", key: "PRODUCT_MARKETING" },
	    { name: "Finance",             key: "FINANCE" }
	  ];

	  Promise.all(depts.map(function(d) {
	    return fetch(SCK + "/getUsersByDepartment", {
	      method:  "POST",
	      headers: { "Content-Type": "application/json" },
	      body:    JSON.stringify({ uniqueId: uniqueId, departmentName: d.name })
	    })
	    .then(function(r) { return r.json(); })
	    .then(function(res) {
	      var list = (res && res.status === 200 && Array.isArray(res.data)) ? res.data : [];
	      // Same exclusion as the own-department dropdown in loadUsers().
	      list = list.filter(function(u) { return EXEC_ROLES.indexOf((u.role || "").toUpperCase()) === -1; });
	      list.forEach(function(u) { u.__deptKey = d.key; u.__deptLabel = DEPT_CONFIG[d.key].label; });
	      return list;
	    })
	    .catch(function() { return []; });
	  }))
	  .then(function(results) {
	    var allUsers = [].concat.apply([], results);
	    if (!allUsers.length) {
	      document.getElementById('pageHeadActions').style.display = 'none';
	      document.getElementById('mainCard').style.display = 'none';
	      document.getElementById('noDeptCard').style.display = 'block';
	      return;
	    }

	    document.getElementById('userBar').style.display = 'flex';
	    buildUserDropdown(allUsers);

	    // Default to the viewer's own entry when they themselves belong to one of the three
	    // departments (so a granted Sales/Implementation/Product Marketing user lands on their
	    // own data — Add Activity visible, categories matching their department — instead of
	    // whichever teammate happens to be first in the list).
	    var selfId = sessionStorage.getItem("userId");
	    var selfUser = allUsers.find(function(u) { return String(u.userId) === String(selfId); });
	    selectUser(selfUser || allUsers[0]);
	  });
	}

	/* ─── Pagination state ─── */
	var currentPage = 1;
	var pageSize    = 25;
	
	/* ─── Date Range state ─── */
	var dp = {
	  startSel: null, endSel: null, leftMonth: null, picking: false
	};
	
	/* Initialize to "This Month" */
	(function(){
	  var today = new Date();
	  var first = new Date(today.getFullYear(), today.getMonth(), 1);
	  var last  = new Date(today.getFullYear(), today.getMonth() + 1, 0);
	  dp.startSel  = first;
	  dp.endSel    = last;
	  dp.leftMonth = new Date(first.getFullYear(), first.getMonth(), 1);
	})();
	
	/* =============== DATE HELPERS =============== */
	function toDbDate(iso)  { if(!iso) return null; var p=iso.split('-'); return p[2]+'-'+p[1]+'-'+p[0]; }
	function toIsoDate(dmy) { if(!dmy) return ''; var p=dmy.split('-'); return p[2]+'-'+p[1]+'-'+p[0]; }
	function todayIso() {
	  var d = new Date();
	  return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
	}

	/* ── Date-group helpers (recent-activity timeline) ── */
	function dgParseDMY(dmy) {
	  if (!dmy) return null;
	  var p = dmy.split('-');
	  if (p.length !== 3) return null;
	  return new Date(+p[2], (+p[1]) - 1, +p[0]);
	}
	function dgRelativeLabel(dmy) {
	  var d = dgParseDMY(dmy);
	  if (!d) return '';
	  var today = dpStripTime(new Date());
	  var yest  = new Date(today); yest.setDate(yest.getDate() - 1);
	  var cur   = dpStripTime(d);
	  if (dpSameDay(cur, today)) return 'Today';
	  if (dpSameDay(cur, yest))  return 'Yesterday';
	  return '';
	}
	function dgWeekday(dmy) {
	  var d = dgParseDMY(dmy);
	  if (!d) return '';
	  var w = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
	  return w[d.getDay()];
	}

	/* ── Date picker helpers ── */
	function dpPad(n) { return (n < 10 ? '0' : '') + n; }
	function dpFmt(d) { return dpPad(d.getDate())+'-'+dpPad(d.getMonth()+1)+'-'+d.getFullYear(); }
	function dpFmtLabel(d) {
	  var m = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
	  return m[d.getMonth()]+' '+d.getDate()+', '+d.getFullYear();
	}
	function dpStripTime(d) { return new Date(d.getFullYear(), d.getMonth(), d.getDate()); }
	function dpSameDay(a,b) { return a && b && a.getTime() === b.getTime(); }
	function dpAddMonths(d,n) { return new Date(d.getFullYear(), d.getMonth()+n, 1); }
	
	/* ── Toggle / Open / Close ── */
	function dpToggle(event) {
	  if(event) event.stopPropagation();
	  var pop = document.getElementById('dpPopover');
	  if(pop.classList.contains('open')) dpClose(); else dpOpen();
	}
	function dpOpen() {
	  dp.picking = false;
	  var base = dp.startSel || new Date();
	  dp.leftMonth = new Date(base.getFullYear(), base.getMonth(), 1);
	  dpHighlightPreset();
	  dpRender();
	  document.getElementById('dpPopover').classList.add('open');
	}
	function dpClose() {
	  document.getElementById('dpPopover').classList.remove('open');
	}
	
	/* ── Render Calendars ── */
	function dpRenderMonth(containerId, monthDate, isLeft) {
	  var dow = ['SU','MO','TU','WE','TH','FR','SA'];
	  var year = monthDate.getFullYear(), month = monthDate.getMonth();
	  var first = new Date(year, month, 1);
	  var startDow = first.getDay();
	  var daysInMonth = new Date(year, month+1, 0).getDate();
	  var monthNames = ['January','February','March','April','May','June',
	                    'July','August','September','October','November','December'];
	
	  var html = '<div class="dp-cal-head">';
	  html += '<button type="button" class="dp-nav '+(isLeft?'':'dp-hidden')+'" onclick="dpShift(-1,event)"><i class="fa fa-chevron-left"></i></button>';
	  html += '<span class="dp-month">'+monthNames[month]+' '+year+'</span>';
	  html += '<button type="button" class="dp-nav '+(isLeft?'dp-hidden':'')+'" onclick="dpShift(1,event)"><i class="fa fa-chevron-right"></i></button>';
	  html += '</div><div class="dp-grid">';
	  dow.forEach(function(d){ html += '<div class="dp-dow">'+d+'</div>'; });
	
	  for(var i=0; i<startDow; i++) html += '<div class="dp-day dp-empty"></div>';
	
	  for(var day=1; day<=daysInMonth; day++){
	    var cur = dpStripTime(new Date(year, month, day));
	    var cls = 'dp-day';
	    var s = dp.startSel ? dpStripTime(dp.startSel) : null;
	    var e = dp.endSel   ? dpStripTime(dp.endSel)   : null;
	
	    if(s && e){
	      if(cur.getTime() > s.getTime() && cur.getTime() < e.getTime()) cls += ' dp-in-range';
	      if(dpSameDay(cur,s)) cls += ' dp-range-end dp-range-start';
	      if(dpSameDay(cur,e)) cls += ' dp-range-end dp-range-finish';
	    } else if(s && dpSameDay(cur,s)){
	      cls += ' dp-range-end dp-range-start dp-range-finish';
	    }
	    html += '<div class="'+cls+'" onclick="dpPick('+year+','+month+','+day+',event)">'+day+'</div>';
	  }
	  html += '</div>';
	  document.getElementById(containerId).innerHTML = html;
	}
	
	function dpRender() {
	  dpRenderMonth('dpCalLeft',  dp.leftMonth, true);
	  dpRenderMonth('dpCalRight', dpAddMonths(dp.leftMonth, 1), false);
	  dpUpdateFooter();
	}
	
	function dpShift(n, event) {
	  if(event) event.stopPropagation();
	  dp.leftMonth = dpAddMonths(dp.leftMonth, n);
	  dpRender();
	}
	
	function dpPick(y, m, d, event) {
	  if(event) event.stopPropagation();
	  var clicked = dpStripTime(new Date(y, m, d));
	  if(!dp.picking){
	    dp.startSel = clicked; dp.endSel = null; dp.picking = true;
	  } else {
	    if(clicked.getTime() < dp.startSel.getTime()){
	      dp.endSel = dp.startSel; dp.startSel = clicked;
	    } else {
	      dp.endSel = clicked;
	    }
	    dp.picking = false;
	  }
	  dpClearPresetHighlight();
	  dpRender();
	}
	
	function dpUpdateFooter() {
	  var lbl = document.getElementById('dpSelLabel');
	  var applyBtn = document.getElementById('dpApply');
	  if(dp.startSel && dp.endSel){
	    lbl.innerHTML = '<strong>'+dpFmtLabel(dp.startSel)+'</strong> &mdash; <strong>'+dpFmtLabel(dp.endSel)+'</strong>';
	    applyBtn.disabled = false;
	  } else if(dp.startSel){
	    lbl.innerHTML = '<strong>'+dpFmtLabel(dp.startSel)+'</strong> &mdash; pick end date';
	    applyBtn.disabled = true;
	  } else {
	    lbl.textContent = 'Select a range'; applyBtn.disabled = true;
	  }
	}
	
	/* ── Presets ── */
	function dpClearPresetHighlight() {
	  var btns = document.querySelectorAll('#dpPresets .dp-preset');
	  for(var i=0;i<btns.length;i++) btns[i].classList.remove('active');
	}
	
	function dpHighlightPreset() {
	  dpClearPresetHighlight();
	  if(!dp.startSel || !dp.endSel) return;
	  var s = dpStripTime(dp.startSel), e = dpStripTime(dp.endSel);
	  var today = dpStripTime(new Date());
	
	  function range(name){
	    var start, end;
	    switch(name){
	      case 'today':       start=today; end=today; break;
	      case 'yesterday':   start=new Date(today); start.setDate(start.getDate()-1); end=new Date(start); break;
	      case 'last7':       end=today; start=new Date(today); start.setDate(start.getDate()-6); break;
	      case 'thisMonth':   start=new Date(today.getFullYear(),today.getMonth(),1); end=new Date(today.getFullYear(),today.getMonth()+1,0); break;
	      case 'lastMonth':   start=new Date(today.getFullYear(),today.getMonth()-1,1); end=new Date(today.getFullYear(),today.getMonth(),0); break;
	      case 'last3Months': start=new Date(today.getFullYear(),today.getMonth()-2,1); end=new Date(today.getFullYear(),today.getMonth()+1,0); break;
	      default: return null;
	    }
	    return { start:dpStripTime(start), end:dpStripTime(end) };
	  }
	
	  var presets = ['today','yesterday','last7','thisMonth','lastMonth','last3Months'];
	  var matched = null;
	  for(var i=0;i<presets.length;i++){
	    var r = range(presets[i]);
	    if(r && dpSameDay(r.start,s) && dpSameDay(r.end,e)){ matched=presets[i]; break; }
	  }
	
	  var btns = document.querySelectorAll('#dpPresets .dp-preset');
	  for(var j=0;j<btns.length;j++){
	    if(btns[j].getAttribute('data-preset') === (matched || 'custom'))
	      btns[j].classList.add('active');
	  }
	}
	
	function dpApplyPreset(name, btn) {
	  var today = dpStripTime(new Date());
	  var start, end;
	  switch(name){
	    case 'today':       start=today; end=today; break;
	    case 'yesterday':   start=new Date(today); start.setDate(start.getDate()-1); end=new Date(start); break;
	    case 'last7':       end=today; start=new Date(today); start.setDate(start.getDate()-6); break;
	    case 'thisMonth':   start=new Date(today.getFullYear(),today.getMonth(),1); end=new Date(today.getFullYear(),today.getMonth()+1,0); break;
	    case 'lastMonth':   start=new Date(today.getFullYear(),today.getMonth()-1,1); end=new Date(today.getFullYear(),today.getMonth(),0); break;
	    case 'last3Months': start=new Date(today.getFullYear(),today.getMonth()-2,1); end=new Date(today.getFullYear(),today.getMonth()+1,0); break;
	    case 'custom':      dpClearPresetHighlight(); if(btn) btn.classList.add('active'); dp.picking=false; return;
	  }
	  dp.startSel = dpStripTime(start);
	  dp.endSel   = dpStripTime(end);
	  dp.picking  = false;
	  dp.leftMonth = new Date(dp.startSel.getFullYear(), dp.startSel.getMonth(), 1);
	  dpClearPresetHighlight();
	  if(btn) btn.classList.add('active');
	  dpRender();
	}
	
	function dpApply() {
	  if(!dp.startSel || !dp.endSel) return;
	  dpSetTriggerLabel();
	  dpClose();
	  currentPage = 1;
	  loadList();
	}
	
	function dpSetTriggerLabel() {
	  if(dp.startSel && dp.endSel){
	    document.getElementById('dateRangeLabel').textContent =
	      dpFmtLabel(dp.startSel) + ' \\u2013 ' + dpFmtLabel(dp.endSel);
	  }
	}
	
	/* Wire up preset buttons + outside-click close */
	document.addEventListener('DOMContentLoaded', function(){
	  dpSetTriggerLabel();
	  var presetWrap = document.getElementById('dpPresets');
	  if(presetWrap){
	    presetWrap.addEventListener('click', function(ev){
	      var btn = ev.target.closest('.dp-preset');
	      if(btn) dpApplyPreset(btn.getAttribute('data-preset'), btn);
	    });
	  }
	  document.addEventListener('click', function(ev){
	    var pop = document.getElementById('dpPopover');
	    var trg = document.getElementById('dpTrigger');
	    if(pop && pop.classList.contains('open') &&
	       !pop.contains(ev.target) && !trg.contains(ev.target)){
	      dpClose();
	    }
	  });
	});
	
	/* =============== MODAL OPEN/CLOSE =============== */
	function openModal(title) {
	  document.getElementById('modalTitle').innerText = title || 'Add Activity';
	  document.getElementById('activityModal').classList.add('open');
	}
	function closeModal() {
	  document.getElementById('activityModal').classList.remove('open');
	  clearErrors();
	}
	function clearErrors() {
	  ['errDate','errClient','errClientNew','errActivityType','errFromTime','errToTime']
	    .forEach(function(id){ document.getElementById(id).classList.remove('show'); });
	}
	function resetForm() {
	  editingId = null;
	  document.getElementById('fDate').max          = todayIso();   // no future dates
	  document.getElementById('fDate').value        = todayIso();
	  document.getElementById('fClientSearch').value = '';
	  document.getElementById('fClientNewSearch').value = '';
	  document.getElementById('fActivityType').value = '';
	  document.getElementById('fFromTime').value     = '';
	  document.getElementById('fToTime').value       = '';
	  // document.getElementById('fDuration').value     = '';
	  document.getElementById('fDiscussion').value   = '';
	  document.getElementById('fNextSteps').value    = '';
	  document.getElementById('fFollowUp').value     = '';
	  document.getElementById('fRemarks').value      = '';
	  setAccountType('EXISTING');
	  document.getElementById('clientDropdown').classList.remove('open');
	  document.getElementById('clientDropdownNew').classList.remove('open');
	}
	
	/* =============== ACCOUNT TYPE TOGGLE =============== */
	function setAccountType(t) {
	  accountType = t;
	  document.getElementById('segExisting').classList.toggle('active', t === 'EXISTING');
	  document.getElementById('segNew')     .classList.toggle('active', t === 'NEW');
	  document.getElementById('rowExisting').style.display = t === 'EXISTING' ? '' : 'none';
	  document.getElementById('rowNew')     .style.display = t === 'NEW'      ? '' : 'none';

	  /* Preload the Chasing/Prospective list the moment "New" is selected,
	     same as Existing's Master list preloads when the modal opens. */
	  if (t === 'NEW' && !document.getElementById('fClientNewSearch').value.trim()) {
	    fetchNewAccounts('');
	  }
	}
	
	/* =============== ACCOUNT SEARCH (Existing → Master, New → Chasing/Prospective) =============== */
	document.getElementById('fClientSearch').addEventListener('input', function(e) {
	  var q = e.target.value;
	  clearTimeout(searchTimer);
	  searchTimer = setTimeout(function() { fetchExistingAccounts(q); }, 250);
	});
	document.getElementById('fClientSearch').addEventListener('focus', function() {
	  var dd = document.getElementById('clientDropdown');
	  if (!dd.classList.contains('open')) fetchExistingAccounts(this.value.trim());
	});

	document.getElementById('fClientNewSearch').addEventListener('input', function(e) {
	  var q = e.target.value;
	  clearTimeout(searchTimer);
	  searchTimer = setTimeout(function() { fetchNewAccounts(q); }, 250);
	});
	document.getElementById('fClientNewSearch').addEventListener('focus', function() {
	  var dd = document.getElementById('clientDropdownNew');
	  if (!dd.classList.contains('open')) fetchNewAccounts(this.value.trim());
	});

	document.addEventListener('click', function(e) {
	  if (!e.target.closest('.client-search')) {
	    document.getElementById('clientDropdown').classList.remove('open');
	    document.getElementById('clientDropdownNew').classList.remove('open');
	  }
	});

	/* Shared fetch against one lifecycle stage of the Sales account master. */
	function fetchAccountStage(stage, userIdForStage, searchText) {
	  return fetch(CTX + "/salesDMR/getAccountMaster", {
	    method: "POST",
	    headers: { "Content-Type": "application/json" },
	    body: JSON.stringify({
	      lifecycleStage: stage, page: 1, size: 10,
	      searchText: searchText || "",
	      uniqueId: sessionStorage.getItem("uniqueId"), userId: userIdForStage
	    })
	  })
	  .then(function(r){ return r.json(); })
	  .then(function(json){ return (json && json.data && json.data.records) || []; })
	  .catch(function(err){ console.error(err); return []; });
	}

	/* Wires click-to-select on every ".row" inside dd, filling targetInputId. */
	function wireDropdownRows(dd, targetInputId) {
	  var rows = dd.querySelectorAll('.row');
	  for (var j = 0; j < rows.length; j++) {
	    rows[j].addEventListener('click', function() {
	      document.getElementById(targetInputId).value = decodeURIComponent(this.getAttribute('data-name'));
	      dd.classList.remove('open');
	    });
	  }
	}

	/* Existing → MASTER accounts only (userId "all" — the full account master). */
	function fetchExistingAccounts(searchText) {
	  var dd = document.getElementById('clientDropdown');
	  dd.innerHTML = '<div class="empty"><i class="fa fa-spinner fa-spin" style="margin-right:5px;"></i>Searching…</div>';
	  dd.classList.add('open');

	  fetchAccountStage("MASTER", "all", searchText).then(function(records) {
	    var html = '<div class="row" data-name="N%2FA">N/A</div>';
	    if (!records.length) {
	      html += '<div class="empty">No accounts found</div>';
	    } else {
	      for (var i = 0; i < records.length; i++) {
	        var name = safe(records[i].companyName || '');
	        html += '<div class="row" data-name="'+ encodeURIComponent(records[i].companyName || '') +'">'+ name +'</div>';
	      }
	    }
	    dd.innerHTML = html;
	    wireDropdownRows(dd, 'fClientSearch');
	  })
	  .catch(function(err){ console.error(err); dd.innerHTML = '<div class="empty">Failed to load</div>'; });
	}

	/* New → CHASING + PROSPECTIVE accounts. Scoped to this SPOC's own accounts only for
	   Sales-department reps; execs and non-Sales departments (Product & Marketing) don't
	   own Sales account-master records themselves, so they see the full list — same
	   isExec/isSales fallback convention as salesDMRChasing.jsp's fetchUserId. */
	function fetchNewAccounts(searchText) {
	  var dd = document.getElementById('clientDropdownNew');
	  dd.innerHTML = '<div class="empty"><i class="fa fa-spinner fa-spin" style="margin-right:5px;"></i>Searching…</div>';
	  dd.classList.add('open');

	  var selfUserId  = sessionStorage.getItem("userId");
	  var selfRole    = (sessionStorage.getItem("role") || "").toUpperCase();
	  var isExec      = EXEC_ROLES.indexOf(selfRole) > -1;
	  var isSalesDept = ACTIVE_DEPT === DEPT_CONFIG.SALES;
	  var fetchUserId = (isExec || !isSalesDept) ? "all" : selfUserId;

	  Promise.all([
	    fetchAccountStage("CHASING",     fetchUserId, searchText),
	    fetchAccountStage("PROSPECTIVE", fetchUserId, searchText)
	  ])
	  .then(function(results) {
	    var groups = [
	      { stage: 'chasing',     icon: 'fa-bolt',     label: 'Chasing',     records: results[0] },
	      { stage: 'prospective', icon: 'fa-seedling', label: 'Prospective', records: results[1] }
	    ];

	    var hasAny = groups.some(function(g){ return g.records.length > 0; });

	    var html = '<div class="row" data-name="N%2FA">N/A</div>';
	    if (!hasAny) { html += '<div class="empty">No accounts found</div>'; dd.innerHTML = html; wireDropdownRows(dd, 'fClientNewSearch'); return; }

	    groups.forEach(function(g) {
	      if (!g.records.length) return;
	      html += '<div class="dropdown-group-label"><i class="fa '+ g.icon +'"></i> '+ g.label +'</div>';
	      for (var i = 0; i < g.records.length; i++) {
	        var name = safe(g.records[i].companyName || '');
	        html += '<div class="row" data-name="'+ encodeURIComponent(g.records[i].companyName || '') +'">'
	              +   '<span>'+ name +'</span>'
	              +   '<span class="stage-badge stage-'+ g.stage +'">'+ g.label +'</span>'
	              +   '</div>';
	      }
	    });
	    dd.innerHTML = html;
	    wireDropdownRows(dd, 'fClientNewSearch');
	  })
	  .catch(function(err){ console.error(err); dd.innerHTML = '<div class="empty">Failed to load</div>'; });
	}
	
	/* =============== DURATION AUTO-CALC =============== */
	function recalcDuration() {
	  var f = document.getElementById('fFromTime').value;
	  var t = document.getElementById('fToTime').value;
	  document.getElementById('errToTime').classList.remove('show');
	  if (!f || !t) return;
	  if (toMinutes(t) <= toMinutes(f)) {
	    document.getElementById('errToTime').classList.add('show');
	  }
	}
	function toMinutes(hhmm) { var p = hhmm.split(':'); return parseInt(p[0],10)*60 + parseInt(p[1],10); }
	
	document.getElementById('fFromTime').addEventListener('change', recalcDuration);
	document.getElementById('fToTime')  .addEventListener('change', recalcDuration);
	
	/* =============== SAVE =============== */
	function saveActivity() {
	  clearErrors();
	
	  var dateIso = document.getElementById('fDate').value;
	  var clientName = accountType === 'EXISTING'
	      ? document.getElementById('fClientSearch').value.trim()
	      : document.getElementById('fClientNewSearch').value.trim();
	  var activityType = document.getElementById('fActivityType').value;
	  var fromTime = document.getElementById('fFromTime').value;
	  var toTime   = document.getElementById('fToTime').value;

	  var ok = true;
	  var errDateEl = document.getElementById('errDate');
	  if (!dateIso) {
	    errDateEl.textContent = 'Date is required';
	    errDateEl.classList.add('show'); ok = false;
	  } else if (dateIso > todayIso()) {
	    errDateEl.textContent = 'Date cannot be in the future';
	    errDateEl.classList.add('show'); ok = false;
	  }
	  if (!clientName)   {
	    document.getElementById(accountType === 'EXISTING' ? 'errClient' : 'errClientNew').classList.add('show');
	    ok = false;
	  }
	  if (!activityType) { document.getElementById('errActivityType').classList.add('show'); ok = false; }
	  if (!fromTime)     { document.getElementById('errFromTime').classList.add('show'); ok = false; }
	  if (!toTime)       { document.getElementById('errToTime').classList.add('show'); ok = false; }
	  if (fromTime && toTime && toMinutes(toTime) <= toMinutes(fromTime)) {
	    document.getElementById('errToTime').classList.add('show'); ok = false;
	  }
	  if (!ok) return;

	  getGeoLocationString().then(function(geoLoc){
	    var payload = {
	      id:                editingId,
	      activityDate:      toDbDate(dateIso),
	      accountType:       accountType,
	      clientName:        clientName,
	      activityType:      activityType,
	      fromTime:          fromTime,
	      toTime:            toTime,
	      discussionSummary: document.getElementById('fDiscussion').value,
	      nextSteps:         document.getElementById('fNextSteps').value,
	      nextFollowUpDate:  toDbDate(document.getElementById('fFollowUp').value),
	      remarks:           document.getElementById('fRemarks').value,
	      geoLoc:            geoLoc
	    };

	    fetch(CTX + "/dailyActivity/" + ACTIVE_DEPT.endpoints.save, {
	      method:  "POST",
	      headers: { "Content-Type": "application/json" },
	      body:    JSON.stringify(payload)
	    })
	    .then(function(r){ return r.json(); })
	    .then(function(json){
	      if (json.status !== 200) { alert(json.message || 'Save failed'); return; }
	      closeModal();
	      loadList();
	    })
	    .catch(function(err){ console.error(err); alert('Save failed'); });
	  });
	}

	/* =============== GEOLOCATION =============== */
	/* Resolves to "lat,long" (paste straight into Google Maps to pinpoint the spot),
	   or null if the browser lacks geolocation, the user denies it, or it times out.
	   Never blocks the save on a missing/denied location. */
	function getGeoLocationString() {
	  return new Promise(function(resolve) {
	    if (!navigator.geolocation) { resolve(null); return; }
	    navigator.geolocation.getCurrentPosition(
	      function(pos) {
	        resolve(pos.coords.latitude.toFixed(6) + ',' + pos.coords.longitude.toFixed(6));
	      },
	      function() { resolve(null); },
	      { enableHighAccuracy: true, timeout: 5000, maximumAge: 60000 }
	    );
	  });
	}
	
	/* =============== SEARCH (debounced) =============== */
	var filterTimer = null;
	document.getElementById('filterSearch').addEventListener('input', function() {
	  clearTimeout(filterTimer);
	  filterTimer = setTimeout(function(){ currentPage = 1; loadList(); }, 400);
	});
	document.getElementById('filterSearch').addEventListener('keydown', function(e) {
	  if (e.key === 'Enter') { clearTimeout(filterTimer); currentPage = 1; loadList(); }
	});
	
	/* =============== LIST (PAGINATED) =============== */
	function loadList() {
	  var searchText = document.getElementById('filterSearch').value.trim();
	
	  var fromDate = dp.startSel ? dpFmt(dp.startSel) : null;
	  var toDate   = dp.endSel   ? dpFmt(dp.endSel)   : null;
	
	  var payload = {
	    uniqueId: selectedUniqueId || sessionStorage.getItem("uniqueId"),
	    userId:   selectedUserId || sessionStorage.getItem("userId"),
	    page:     String(currentPage),
	    size:     String(pageSize)
	  };
	  if (searchText) payload.searchText = searchText;
	  if (fromDate)   payload.fromDate   = fromDate;
	  if (toDate)     payload.toDate     = toDate;
	
	  var tb = document.getElementById('activityTbody');
	  tb.innerHTML = '<tr><td colspan="13" style="text-align:center;color:var(--slate-400);padding:24px;">' +
	    '<i class="fa fa-spinner fa-spin" style="margin-right:6px;"></i>Loading…</td></tr>';

	  fetch(CTX + "/dailyActivity/" + ACTIVE_DEPT.endpoints.list, {
	    method:  "POST",
	    headers: { "Content-Type": "application/json" },
	    body:    JSON.stringify(payload)
	  })
	  .then(function(r){ return r.json(); })
	  .then(function(json){
	    if (json.status !== 200) {
	      tb.innerHTML = '<tr><td colspan="13" class="empty-state"><p>' + safe(json.message) + '</p></td></tr>';
	      hidePagination(); return;
	    }

	    var data    = json.data || {};
	    var records = data.records      || [];
	    var total   = data.totalRecords || 0;
	    var pages   = data.totalPages   || 1;
	    var page    = data.currentPage  || 1;

	    if (!records.length) {
	      tb.innerHTML = '<tr><td colspan="13" class="empty-state" style="padding:60px 20px;">' +
	        '<i class="fa fa-chart-line" style="font-size:40px;margin-bottom:12px;display:block;opacity:.4;"></i>' +
	        '<p style="font-size:14px;">No activities found.</p></td></tr>';
	      hidePagination(); return;
	    }

	    /* Group the page's records by date — most recent date first — and show
	       a day header (date + total duration for that day) above each group. */
	    var startIdx  = (page - 1) * pageSize;
	    var groupsMap = {};
	    var order     = [];
	    for (var gi = 0; gi < records.length; gi++) {
	      var gr  = records[gi];
	      var key = gr.activityDate || 'Unknown';
	      if (!groupsMap[key]) { groupsMap[key] = { records: [], totalDuration: 0 }; order.push(key); }
	      groupsMap[key].records.push(gr);
	      groupsMap[key].totalDuration += (parseInt(gr.duration, 10) || 0);
	    }
	    order.sort(function(a, b) {
	      var da = dgParseDMY(a), db = dgParseDMY(b);
	      if (!da || !db) return 0;
	      return db.getTime() - da.getTime();
	    });

	    var html = '';
	    var sno  = startIdx;
	    for (var gk = 0; gk < order.length; gk++) {
	      var dateKey = order[gk];
	      var grp     = groupsMap[dateKey];
	      var rel     = dgRelativeLabel(dateKey);

	      /* Centered pill header — date, relative label, activity count & total
	         duration all in one line, matching the sck360/userTimeSheet style. */
	      html += '<tr class="day-header-row"><td colspan="13">'
	        + '<div class="day-group-label" style="animation-delay:'+ (gk * 45) +'ms;">'
	        +   '<span class="day-group-pill">'
	        +     '<i class="fa fa-calendar-day"></i> '+ safe(dateKey)
	        +     (rel ? ' <span class="dg-relative">'+ rel +'</span>' : ' ('+ dgWeekday(dateKey) +')')
	        +     ' <span class="dg-sep">&bull;</span> '+ grp.records.length +' '+ (grp.records.length === 1 ? 'activity' : 'activities')
	        +     ' <span class="dg-sep">&bull;</span> <span class="dg-duration"><i class="fa fa-hourglass-half"></i> '+ (fmtDuration(grp.totalDuration) || '0 Mins') +'</span>'
	        +   '</span>'
	        + '</div>'
	        + '</td></tr>';

	      for (var ri = 0; ri < grp.records.length; ri++) {
	        var r = grp.records[ri];
	        sno++;
	        var badge = r.accountType === 'NEW'
	          ? '<span class="badge badge-new">New</span>'
	          : '<span class="badge badge-existing">Existing</span>';
	        html += '<tr class="row-clickable" onclick="viewRow('+ r.id +')">'
	          + '<td data-label="S.No">'+ sno +'.</td>'
	          + '<td data-label="SPOC Name">'+ safe(r.spocName) +'</td>'
	          + '<td data-label="Client"><strong style="color:var(--green-primary);">'+ safe(r.clientName) +'</strong></td>'
	          + '<td data-label="Type">'+ badge +'</td>'
	          + '<td data-label="Activity">'+ (r.activityType ? '<span class="badge" style="background:#e0f2fe;color:#0369a1;">' + safe(r.activityType) + '</span>' : '—') +'</td>'
	          + '<td data-label="From">'+ safe(r.fromTime) +'</td>'
	          + '<td data-label="To">'+ safe(r.toTime) +'</td>'
	          + '<td data-label="Duration">'+ fmtDuration(r.duration) +'</td>'
	          + '<td class="wrap" data-label="Discussion"><span title="'+ escAttr(r.discussionSummary) +'">'+ truncate(r.discussionSummary, 40) +'</span></td>'
	          + '<td class="wrap" data-label="Next Steps"><span title="'+ escAttr(r.nextSteps) +'">'+ truncate(r.nextSteps, 30) +'</span></td>'
	          + '<td style="white-space:nowrap;" data-label="Follow-up">'+ safe(r.nextFollowUpDate) +'</td>'
	          + '<td class="wrap" data-label="Remarks"><span title="'+ escAttr(r.remarks) +'">'+ truncate(r.remarks, 30) +'</span></td>'
	          // VAPT fix — this "Update" action rendered for every row unconditionally, including
	          // rows belonging to whoever's data is being viewed via VIEW_ALL_MODE, not just your
	          // own — the only other own-data gate on this page (btnAddActivity, above) was never
	          // applied here. Same isViewingOwnData flag, same treatment: no actions menu at all
	          // on a row that isn't yours, matching "Add Activity" already being hidden that way.
	          + '<td class="col-actions" data-label="Actions" onclick="event.stopPropagation();">'
	          +   (isViewingOwnData ?
	                '<div class="row-menu-wrap">'
	          +     '<button type="button" class="row-menu-btn" onclick="toggleRowMenu(event,'+ r.id +')" title="Actions"><i class="fa fa-ellipsis-vertical"></i></button>'
	          +     '<div class="row-menu-dropdown" id="rowMenu'+ r.id +'">'
	          +       '<button type="button" onclick="closeAllRowMenus(); editRow('+ r.id +');"><i class="fa fa-pen"></i> Update</button>'
	          +     '</div>'
	          +   '</div>'
	              : '')
	          + '</td>'
	          + '</tr>';
	      }
	    }
	    tb.innerHTML = html;
	    window.__activities = records;
	    renderPagination(page, pages, total);
	  })
	  .catch(function(err){ console.error(err); });
	}
	
	function fmtDuration(mins) {
		  if (mins == null || mins === '') return '';
		  mins = parseInt(mins, 10);
		  if (isNaN(mins) || mins <= 0) return '';
		  if (mins < 60) return mins + ' Mins';
		  var h = Math.floor(mins / 60);
		  var m = mins % 60;
		  return m > 0 ? h + ' Hr ' + m + ' Mins' : h + ' Hr';
		}
	
	/* =============== PAGINATION =============== */
	function renderPagination(page, totalPages, totalRecords) {
	  var bar  = document.getElementById('paginationBar');
	  var info = document.getElementById('pageInfo');
	  var btns = document.getElementById('pageBtns');
	
	  if (totalPages <= 1 && totalRecords <= pageSize) { bar.style.display='none'; return; }
	  bar.style.display = 'flex';
	
	  var from = (page - 1) * pageSize + 1;
	  var to   = Math.min(page * pageSize, totalRecords);
	  info.textContent = 'Showing ' + from + '–' + to + ' of ' + totalRecords;
	
	  var html = '';
	  html += '<button '+(page<=1?'disabled':'onclick="goToPage('+(page-1)+')"')+'><i class="fa fa-chevron-left" style="font-size:10px;"></i></button>';
	
	  var startP = Math.max(1, page - 2), endP = Math.min(totalPages, page + 2);
	  if (startP > 1) {
	    html += '<button onclick="goToPage(1)">1</button>';
	    if (startP > 2) html += '<button disabled>…</button>';
	  }
	  for (var p = startP; p <= endP; p++) {
	    html += '<button class="'+(p===page?'active':'')+'" onclick="goToPage('+p+')">'+p+'</button>';
	  }
	  if (endP < totalPages) {
	    if (endP < totalPages - 1) html += '<button disabled>…</button>';
	    html += '<button onclick="goToPage('+totalPages+')">'+totalPages+'</button>';
	  }
	  html += '<button '+(page>=totalPages?'disabled':'onclick="goToPage('+(page+1)+')"')+'><i class="fa fa-chevron-right" style="font-size:10px;"></i></button>';
	  btns.innerHTML = html;
	}
	
	function goToPage(p) {
	  currentPage = p;
	  loadList();
	  document.querySelector('.tbl-wrap').scrollTop = 0;
	}
	function hidePagination() { document.getElementById('paginationBar').style.display='none'; }
	
	/* =============== HELPERS =============== */
	function safe(v) { if (v==null) return ''; return String(v).replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
	function truncate(v, max) {
	  if (!v) return '<span style="color:var(--slate-400);">—</span>';
	  var s = safe(v);
	  return s.length > max ? s.substring(0, max) + '…' : s;
	}
	
	function editRow(id) {
	  // VAPT fix -- belt-and-suspenders: the button that calls this is now hidden unless
	  // isViewingOwnData, but guard the function itself too against being invoked directly
	  // (e.g. from the browser console). Real protection is server-side (the ownership check
	  // in DailyActivityService) -- this just stops the UI opening an edit form for
	  // someone else's activity in the first place.
	  if (!isViewingOwnData) return;
	  var row = null, arr = window.__activities || [];
	  for (var i = 0; i < arr.length; i++) if (arr[i].id === id) { row = arr[i]; break; }
	  if (!row) return;
	
	  resetForm();
	  editingId = id;
	  setAccountType(row.accountType || 'EXISTING');
	  document.getElementById('fDate').value         = toIsoDate(row.activityDate);
	  if (row.accountType === 'NEW') document.getElementById('fClientNewSearch').value = row.clientName || '';
	  else                           document.getElementById('fClientSearch').value = row.clientName || '';
	  document.getElementById('fActivityType').value = row.activityType || '';
	  document.getElementById('fFromTime').value     = row.fromTime || '';
	  document.getElementById('fToTime').value       = row.toTime   || '';
	  document.getElementById('fDiscussion').value   = row.discussionSummary || '';
	  document.getElementById('fNextSteps').value    = row.nextSteps || '';
	  document.getElementById('fFollowUp').value     = toIsoDate(row.nextFollowUpDate);
	  document.getElementById('fRemarks').value      = row.remarks || '';
	  recalcDuration();
	  openModal('Edit Activity');
	}
	
	function deleteRow(id) {
	  if (!confirm('Delete this activity?')) return;
	  fetch(CTX + "/dailyActivity/" + ACTIVE_DEPT.endpoints.delete, {
	    method:  "POST",
	    headers: { "Content-Type": "application/json" },
	    body:    JSON.stringify({ id: id })
	  })
	  .then(function(r){ return r.json(); })
	  .then(function(){ loadList(); });
	}

	/* =============== ROW ACTIONS (3-dot menu) =============== */
	function closeAllRowMenus() {
	  document.querySelectorAll('.row-menu-dropdown.open').forEach(function(m){ m.classList.remove('open'); });
	  document.querySelectorAll('.row-menu-btn.active').forEach(function(b){ b.classList.remove('active'); });
	}
	function toggleRowMenu(event, id) {
	  event.stopPropagation();
	  var menu = document.getElementById('rowMenu' + id);
	  if (!menu) return;
	  var wasOpen = menu.classList.contains('open');
	  closeAllRowMenus();
	  if (!wasOpen) {
	    menu.classList.add('open');
	    event.currentTarget.classList.add('active');
	  }
	}
	document.addEventListener('click', function(e) {
	  if (!e.target.closest('.row-menu-wrap')) closeAllRowMenus();
	});
	document.querySelector('.tbl-wrap').addEventListener('scroll', closeAllRowMenus);

	/* =============== VIEW DETAILS =============== */
	function viewVal(id, v) {
	  var el = document.getElementById(id);
	  if (v === null || v === undefined || v === '') {
	    el.textContent = '—';
	    el.classList.add('empty');
	  } else {
	    el.textContent = v;
	    el.classList.remove('empty');
	  }
	}
	function viewRow(id) {
	  var row = null, arr = window.__activities || [];
	  for (var i = 0; i < arr.length; i++) if (arr[i].id === id) { row = arr[i]; break; }
	  if (!row) return;

	  viewVal('vSpocName',     row.spocName);
	  viewVal('vDate',         row.activityDate);
	  viewVal('vClientName',   row.clientName);
	  viewVal('vAccountType',  row.accountType === 'NEW' ? 'New' : (row.accountType === 'EXISTING' ? 'Existing' : ''));
	  viewVal('vActivityType', row.activityType);
	  viewVal('vFromTime',     row.fromTime);
	  viewVal('vToTime',       row.toTime);
	  viewVal('vDuration',     fmtDuration(row.duration));
	  viewVal('vDiscussion',   row.discussionSummary);
	  viewVal('vNextSteps',    row.nextSteps);
	  viewVal('vFollowUp',     row.nextFollowUpDate);
	  viewVal('vRemarks',      row.remarks);

	  document.getElementById('viewModal').classList.add('open');
	}
	function closeViewModal() {
	  document.getElementById('viewModal').classList.remove('open');
	}

	/* =============== USER DROPDOWN =============== */
	function loadUsers() {
	  var uniqueId = sessionStorage.getItem("uniqueId");
	  var selfId   = sessionStorage.getItem("userId");
	  if (!uniqueId) { loadList(); return; }

	  fetch(SCK + "/getUsersByDepartment", {
	    method:  "POST",
	    headers: { "Content-Type": "application/json" },
	    body:    JSON.stringify({ uniqueId: uniqueId, departmentName: ACTIVE_DEPT.teamDeptName })
	  })
	  .then(function(res) { return res.json(); })
	  .then(function(res) {
	    if (res.status !== 200 || !Array.isArray(res.data) || res.data.length === 0) {
	      loadList(); return;
	    }

	    var selfUser = res.data.find(function(u) {
	      return String(u.userId) === String(selfId);
	    });

	    var isDeptUser = !!selfUser;
	    var isDeptExec = isDeptUser && EXEC_ROLES.indexOf((selfUser.role || "").toUpperCase()) > -1;

	    // Non-exec: no dropdown, own data only
	    if (isDeptUser && !isDeptExec) {
	      selectedUserId   = selfId;
	      selectedUniqueId = uniqueId;
	      selectedUserName = selfUser.name;
	      isViewingOwnData = true;
	      loadList();
	      return;
	    }

	    // Exec OR user outside this department: show dropdown with dept users (excluding CEO/CTO/COO)
	    var dropdownUsers = res.data.filter(function(u) {
	      return EXEC_ROLES.indexOf((u.role || "").toUpperCase()) === -1;
	    });

	    if (dropdownUsers.length === 0) { loadList(); return; }

	    document.getElementById('userBar').style.display = 'flex';
	    buildUserDropdown(dropdownUsers);
	    selectUser(dropdownUsers[0]);
	  })
	  .catch(function(err) {
	    console.warn("Failed to load users:", err);
	    loadList();
	  });
	}

	function buildUserDropdown(users) {
	  var menu = document.getElementById('ubDropdownMenu');
	  menu.innerHTML = '';
	  users.forEach(function(u, idx) {
	    var item = document.createElement('div');
	    item.className = 'ub-dropdown-item' + (idx === 0 ? ' active' : '');
	    item.dataset.userId = u.userId;

	    var avDiv = document.createElement('div');
	    avDiv.className = 'ub-dropdown-avatar';
	    var initials = (u.name || '--').split(' ')
	      .map(function(w) { return w[0] || ''; })
	      .join('').substring(0, 2).toUpperCase();

	    if (u.profilePictureUrl) {
	      var img = document.createElement('img');
	      img.src = CTX + '/sck360/profilePicture?uniqueId='
	        + encodeURIComponent(u.uniqueId || '')
	        + '&userId=' + encodeURIComponent(u.userId || '')
	        + '&t=' + Date.now();
	      img.alt = initials;
	      img.onerror = (function(el, txt) {
	        return function() { el.innerHTML = ''; el.textContent = txt; };
	      })(avDiv, initials);
	      avDiv.appendChild(img);
	    } else {
	      avDiv.textContent = initials;
	    }

	    var roleLine = safe(u.role || '') + (u.__deptLabel ? ' &bull; ' + safe(u.__deptLabel) : '');
	    var infoDiv = document.createElement('div');
	    infoDiv.innerHTML = '<div class="ub-dropdown-name">' + safe(u.name || '') + '</div>'
	      + '<div class="ub-dropdown-role">' + roleLine + '</div>';

	    item.appendChild(avDiv);
	    item.appendChild(infoDiv);
	    item.addEventListener('click', function() {
	      selectUser(u);
	      closeUserDropdown();
	    });
	    menu.appendChild(item);
	  });
	}

	function selectUser(u) {
	  var selfId = sessionStorage.getItem("userId");
	  selectedUserId   = u.userId;
	  selectedUniqueId = u.uniqueId;
	  selectedUserName = u.name;
	  isViewingOwnData = String(u.userId) === String(selfId);

	  // VIEW_ALL_MODE: each switch can land on a different department's user, so re-point
	  // ACTIVE_DEPT (and the badge) at whichever table this user's data actually lives in.
	  if (VIEW_ALL_MODE && u.__deptKey) {
	    applyDeptConfig(u.__deptKey);
	  }

	  document.getElementById('ubSelectedLabel').textContent = u.name + ' (' + (u.role || '') + ')';

	  var avatarEl = document.getElementById('ubAvatar');
	  var initials = (u.name || '--').split(' ')
	    .map(function(w) { return w[0] || ''; })
	    .join('').substring(0, 2).toUpperCase();
	  avatarEl.innerHTML = '';
	  if (u.profilePictureUrl) {
	    var img = document.createElement('img');
	    img.src = CTX + '/sck360/profilePicture?uniqueId='
	      + encodeURIComponent(u.uniqueId || '')
	      + '&userId=' + encodeURIComponent(u.userId || '')
	      + '&t=' + Date.now();
	    img.alt = initials;
	    img.onerror = (function(el, txt) {
	      return function() { el.innerHTML = ''; el.textContent = txt; };
	    })(avatarEl, initials);
	    avatarEl.appendChild(img);
	  } else {
	    avatarEl.textContent = initials;
	  }

	  var items = document.querySelectorAll('#ubDropdownMenu .ub-dropdown-item');
	  for (var i = 0; i < items.length; i++) {
	    items[i].classList.toggle('active', items[i].dataset.userId == u.userId);
	  }

	  document.getElementById('btnAddActivity').style.display = isViewingOwnData ? '' : 'none';
	  currentPage = 1;
	  loadList();
	}

	function closeUserDropdown() {
	  var menu = document.getElementById('ubDropdownMenu');
	  var chevron = document.getElementById('ubChevron');
	  if (menu) menu.classList.remove('open');
	  if (chevron) chevron.style.transform = '';
	}

	document.getElementById('ubSelectedDisplay').addEventListener('click', function() {
	  var menu = document.getElementById('ubDropdownMenu');
	  var chevron = document.getElementById('ubChevron');
	  var isOpen = menu.classList.contains('open');
	  if (isOpen) {
	    menu.classList.remove('open');
	    if (chevron) chevron.style.transform = '';
	  } else {
	    menu.classList.add('open');
	    if (chevron) chevron.style.transform = 'rotate(180deg)';
	  }
	});

	document.addEventListener('click', function(e) {
	  var wrap = document.getElementById('ubCustomSelect');
	  if (wrap && !wrap.contains(e.target)) closeUserDropdown();
	});

	/* =============== EXPORT =============== */
	document.getElementById('btnExport').addEventListener('click', function(e) {
	  e.stopPropagation();
	  document.getElementById('exportMenu').classList.toggle('open');
	});
