       function spocBadge(userId) {
    	    var name = (userNameMap && userNameMap[String(userId)]) ? userNameMap[String(userId)] : "";
    	    if (!name) return '<span style="color:var(--slate-400);font-size:12px;">—</span>';
        if (!name || name === "—") return '<span style="color:var(--slate-400);font-size:12px;">—</span>';
        var sum = 0;
        for (var i = 0; i < name.length; i++) sum += name.charCodeAt(i);
        var pal = _amPalette[sum % _amPalette.length];
        return '<span style="display:inline-flex;align-items:center;padding:3px 12px;border-radius:20px;font-size:12.5px;font-weight:600;background:'+pal.bg+';color:'+pal.color+';">'+name+'</span>';
    }

    /* ═══════════════════════════════════════════════════════════
       ★ NEW — fetch all users and build userNameMap
       Called once during page load.
    ═══════════════════════════════════════════════════════════ */
    function loadUserNames(callback) {
        fetch("/sck360/getUsersBasicDetails", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ uniqueId: uniqueId })
        })
        .then(function(r) { return r.json(); })
        .then(function(resp) {
            var users = resp.data || [];

            users.forEach(function(u) {
                if (u.userId) {
                    userNameMap[String(u.userId)] = u.name || u.userId;
                }
            });

            var selfUser = users.find(function(u) {
                return String(u.userId) === String(userId);
            });

            if (selfUser) {
                var selfRole = (selfUser.role || "").toUpperCase();
                var selfDept = (selfUser.department || "").toUpperCase();
                var isExec   = EXEC_ROLES.indexOf(selfRole) > -1;
                var isSales  = selfDept === "SALES";
                fetchUserId = (isExec || !isSales) ? "all" : userId;
            } else {
                fetchUserId = "all";
            }

            console.log("selfUser:", selfUser, "fetchUserId:", fetchUserId);

            /* ── Show user filter only when this user sees all data ── */
            var wrap = document.getElementById("user-filter-wrap");
            if (wrap) wrap.style.display = (fetchUserId === "all") ? "" : "none";
            if (fetchUserId === "all") loadUserFilterDropdown();

            if (callback) callback();
        })
        .catch(function(err) {
            console.warn("Could not load user names:", err);
            if (callback) callback();
        });
    }
    
    function loadAllAccountMastersForDropdown(callback) {
        fetch(CONTEXT + "/getAccountMaster", {
            method: "POST", headers: {"Content-Type": "application/json"},
            body: JSON.stringify({
                userId: fetchUserId, uniqueId: uniqueId,
                // lifecycleStage: "CHASING",
                page: 1, size: 9999
            })
        })
        .then(function(r) { return r.json(); })
        .then(function(resp) {
            var d = resp.data || {};
            accountMasterAllData = d.records || [];
            if (callback) callback();
        })
        .catch(function() {
            accountMasterAllData = [];
            if (callback) callback();
        });
    }

    /* ─── Init ─── */
    window.addEventListener("load", function () {
        var today = todayISO();
        document.getElementById("dmr-from-date").value = today;
        document.getElementById("dmr-to-date").value   = today;
        toggleDateBar();
        document.getElementById("dynamic-content-container").innerHTML = buildSkeletonTable(9, 14);
        ["tc_date", "li_date", "lid_date"].forEach(function(id) {
            var el = document.getElementById(id);
            if (el) el.setAttribute("max", today);
        });
        loadUserNames(function() {
            loadAllAccountMastersForDropdown(function() {
                loadAccountMasters(1);
            });
        });
    });

    function getDateRange() {
        var fromISO = document.getElementById("dmr-from-date").value;
        var toISO   = document.getElementById("dmr-to-date").value;
        if (!fromISO || !toISO) { alert("Please select both From and To dates."); return null; }
        if (fromISO > toISO)    { alert("From date cannot be after To date."); return null; }
        return { fromDate: isoToDMY(fromISO), toDate: isoToDMY(toISO) };
    }

    function toggleDateBar() {
        var isAM = activeTab === "accountmaster";
        document.getElementById("date-bar").style.display = isAM ? "none" : "flex";
        var rightDiv = document.querySelector(".d-flex.align-items-center.ml-auto");
        if (rightDiv) rightDiv.style.marginLeft = isAM ? "auto" : "0";
    }

    /* ─── Tab switching ─── */
    window.switchDMRTab = function (tab) {
	    activeTab = tab;
	    document.querySelectorAll("#dmrInternalTabs .pn-ProductNav_Link")
	        .forEach(function(el){ el.classList.remove("active"); });
	    document.getElementById("tab_" + tab).classList.add("active");
	    toggleDateBar();
	
	    // Clean up account master pagination when leaving that tab
	    var existingPag = document.getElementById("pagination_am");
	    if (existingPag) existingPag.remove();
	
	    var today = todayISO();
	    if (!document.getElementById("dmr-from-date").value)
	        document.getElementById("dmr-from-date").value = today;
	    if (!document.getElementById("dmr-to-date").value)
	        document.getElementById("dmr-to-date").value = today;
	    loadCurrentTabData();
	};
	
