    /* ════════════════════════════════════════
       CUSTOM SEARCHABLE DROPDOWN ENGINE
    ════════════════════════════════════════ */
    function csdCloseAll(exceptKey) {
        document.querySelectorAll(".custom-select-panel.open").forEach(function(panel){
            if (!exceptKey || panel.id !== exceptKey+"_panel") {
                panel.classList.remove("open");
                var trigger = document.getElementById(panel.id.replace("_panel","_trigger"));
                if (trigger) trigger.classList.remove("open");
            }
        });
    }
    window.csdToggle = function (key) {
        var panel   = document.getElementById(key+"_panel");
        var trigger = document.getElementById(key+"_trigger");
        var isOpen  = panel.classList.contains("open");
        csdCloseAll(key);
        if (!isOpen) {
            csdBuild(key);
            document.getElementById(key+"_search").value = "";
            // For am2_cmp: reset the "use typed name" footer and re-run the combined filter
            if (key === "am2_cmp") {
                document.getElementById("am2_cmp_useNew").style.display = "none";
                csdFilter(key);
            } else {
                csdFilter(key);
            }
            panel.classList.add("open");
            trigger.classList.add("open");
            setTimeout(function(){ document.getElementById(key+"_search").focus(); }, 50);
        }
    };
    
    function csdBuild(key) {
        var list = document.getElementById(key+"_list");
        list.innerHTML = "";
        var hiddenId   = key.replace("_cmp","") + "_companyName";
        var currentVal = document.getElementById(hiddenId).value;
        var sourceData = accountMasterAllData.length ? accountMasterAllData : accountMasterData;
        if (!sourceData.length) {
            var d = document.createElement("div");
            d.className = "custom-select-item no-results";
            d.textContent = "No companies found";
            list.appendChild(d); return;
        }
        sourceData.forEach(function(m){
            var item = document.createElement("div");
            item.className = "custom-select-item" + (m.companyName===currentVal?" selected":"");
            item.textContent = companyLabel(m);
            item.setAttribute("data-value", m.companyName);
            item.onmousedown = function(e){ e.preventDefault(); csdSelect(key, m); };
            list.appendChild(item);
        });
    }
    
    window.csdFilter = function (key) {
        var term  = document.getElementById(key+"_search").value.toLowerCase().trim();
        var items = document.getElementById(key+"_list").querySelectorAll(".custom-select-item:not(.no-results)");
        var vis   = 0;
        items.forEach(function(item){
            var match = !term || item.textContent.toLowerCase().includes(term);
            item.style.display = match ? "" : "none";
            if (match) vis++;
        });
        var noRes = document.getElementById(key+"_list").querySelector(".no-results");
        if (vis===0) {
            if (!noRes) {
                var d = document.createElement("div");
                d.className = "custom-select-item no-results";
                d.textContent = "No matching company";
                document.getElementById(key+"_list").appendChild(d);
            } else { noRes.style.display = ""; }
        } else { if (noRes) noRes.style.display = "none"; }
    };

