    function _amdRenderBatch(batch) {
        var list = document.getElementById("amd_contactsList");
        batch.forEach(function(c, idx) {
            var num  = _amd.shown + idx + 1;
            var card = document.createElement("div");
            card.className = "amd-card";
            var dmHtml = c.decisionMaker === "Yes" ? '<span class="amd-dm-yes">Yes</span>'
                       : c.decisionMaker === "No"  ? '<span class="amd-dm-no">No</span>'
                       : '<span style="color:#94a3b8;">—</span>';
            var lvlHtml   = c.levelOfDM      ? '<span class="amd-lvl">' + c.levelOfDM + '</span>' : "";
            var phoneHtml = c.contactNumber  ? '<span><i class="fa fa-phone" style="font-size:10px;opacity:.6;"></i> ' + c.contactNumber + '</span>' : "";
            var emailHtml = c.mailId         ? '<span><i class="fa fa-envelope" style="font-size:10px;opacity:.6;"></i> ' + c.mailId + '</span>' : "";
            var liHtml    = safeHref(c.linkedIn) ? '<a href="' + safeHref(c.linkedIn) + '" target="_blank"><i class="fa-brands fa-linkedin" style="font-size:11px;"></i> LinkedIn</a>' : "";
            var _pal = _amdPaletteFor(c.personName);
            card.style.borderLeftColor = _pal.color;
            card.style.borderLeftWidth = "4px";
            card.innerHTML =
                '<div class="amd-avatar" style="background:' + _pal.bg + ';color:' + _pal.color + ';">' + escapeHtml(_amdInitials(c.personName)) + '</div>' +
                '<div style="flex:1;min-width:0;">' +
                    '<div class="amd-name">' + num + '. ' + escapeHtml(c.personName || '—') + '</div>' +
                    '<div class="amd-desg">' + escapeHtml(c.designation || '—') + '</div>' +
                    '<div class="amd-meta">' + phoneHtml + emailHtml +
                        '<span>DM: ' + dmHtml + '</span>' + lvlHtml + liHtml +
                    '</div>' +
                '</div>';
            list.appendChild(card);
        });
        _amd.shown += batch.length;
        _amdUpdateFooter();
    }
    function _amdUpdateFooter() {
        var rem = _amd.contacts.length - _amd.shown;
        var btn = document.getElementById("amd_loadMoreBtn");
        var msg = document.getElementById("amd_allShownMsg");
        if (rem <= 0) {
            btn.style.display = "none";
            if (_amd.contacts.length > 0) {
                msg.style.display = "block";
                msg.textContent = "All " + _amd.contacts.length + " person" + (_amd.contacts.length !== 1 ? "s" : "") + " displayed";
            }
        } else {
            btn.style.display = "block"; msg.style.display = "none";
            document.getElementById("amd_loadMoreCount").textContent = Math.min(rem, _amd.PAGE);
        }
    }
    window.amdLoadMore = function() {
        _amdRenderBatch(_amd.contacts.slice(_amd.shown, _amd.shown + _amd.PAGE));
    };
