    function renderPagination(prefix, currentPage, totalPages, loadFn) {
        var existing = document.getElementById("pagination_" + prefix);
        if (existing) existing.remove();

        if (totalPages <= 1) return;

        var wrap = document.createElement("div");
        wrap.id = "pagination_" + prefix;
        wrap.style.cssText = "display:flex;align-items:center;justify-content:center;gap:6px;padding:16px 0 8px;flex-wrap:wrap;";

        function btn(label, page, disabled, active) {
            var b = document.createElement("button");
            b.innerHTML = label;
            b.disabled  = disabled;
            b.style.cssText =
                "min-width:34px;height:34px;border-radius:8px;font-size:13px;font-weight:600;" +
                "border:1.5px solid " + (active ? "#16a34a" : "#e2e8f0") + ";" +
                "background:" + (active ? "#16a34a" : "#fff") + ";" +
                "color:" + (active ? "#fff" : (disabled ? "#cbd5e1" : "#334155")) + ";" +
                "cursor:" + (disabled ? "not-allowed" : "pointer") + ";padding:0 10px;" +
                "transition:background .15s,border-color .15s;";
            if (!disabled && !active) {
                b.onmouseover = function() { this.style.background = "#f0fdf4"; this.style.borderColor = "#86efac"; };
                b.onmouseout  = function() { this.style.background = "#fff";    this.style.borderColor = "#e2e8f0"; };
            }
            if (!disabled) b.onclick = function() { loadFn(page); };
            return b;
        }

        function ellipsis() {
            var s = document.createElement("span");
            s.textContent = "…";
            s.style.cssText = "color:#94a3b8;font-size:13px;padding:0 4px;display:flex;align-items:center;";
            return s;
        }

        /* Prev */
        wrap.appendChild(btn("&larr; Prev", currentPage - 1, currentPage === 1, false));

        var pages = [];

        if (totalPages <= 9) {
            // Small enough — show everything
            for (var i = 1; i <= totalPages; i++) pages.push(i);
        } else {
            var mid = Math.round(totalPages / 2);

            // Always: first 2
            pages.push(1, 2);

            // Left side: gap before current-1?
            if (currentPage - 1 > 3) {
                pages.push("...");
            } else {
                // fill up to current-1 without gap
                for (var i = 3; i < currentPage; i++) pages.push(i);
            }

            // Current neighbourhood (currentPage-1, currentPage, currentPage+1)
            // but don't duplicate first/last 2
            for (var i = Math.max(currentPage - 1, 3); i <= Math.min(currentPage + 1, totalPages - 2); i++) {
                pages.push(i);
            }

            // Middle anchor — only show if it's not near current or first/last blocks
            if (currentPage < mid - 2 && mid > currentPage + 2 && mid < totalPages - 2) {
                pages.push("...");
                pages.push(mid);
            }

            // Right side: gap after current+1?
            if (currentPage + 1 < totalPages - 2) {
                pages.push("...");
            } else {
                // fill from current+1 up to last 2 without gap
                for (var i = Math.max(currentPage + 2, totalPages - 1); i <= totalPages - 2; i++) pages.push(i);
            }

            // Always: last 2
            pages.push(totalPages - 1, totalPages);
        }

        // Deduplicate and sort
        var seen = {};
        var finalPages = [];
        for (var i = 0; i < pages.length; i++) {
            var p = pages[i];
            if (p === "...") {
                // Only add ellipsis if last item wasn't also ellipsis
                if (finalPages[finalPages.length - 1] !== "...") finalPages.push("...");
            } else {
                if (!seen[p]) { seen[p] = true; finalPages.push(p); }
            }
        }

        finalPages.forEach(function(p) {
            if (p === "...") {
                wrap.appendChild(ellipsis());
            } else {
                wrap.appendChild(btn(p, p, false, p === currentPage));
            }
        });

        /* Next */
        wrap.appendChild(btn("Next &rarr;", currentPage + 1, currentPage === totalPages, false));

        /* Page info */
        var info = document.createElement("span");
        info.textContent = "Page " + currentPage + " of " + totalPages;
        info.style.cssText = "font-size:12px;color:#94a3b8;margin-left:8px;";
        wrap.appendChild(info);

        var existing2 = document.getElementById("pagination_" + prefix);
        if (existing2) existing2.remove();
        document.getElementById("dynamic-content-container").after(wrap);
    }
    
