    function loadTelecallingByDate() {
        var range = getDateRange();
        if (!range) return;
        var container = document.getElementById("dynamic-content-container");
        // container.innerHTML='<div style="padding:30px;text-align:center;color:#94a3b8;font-size:13px;">Loading...</div>';
        container.innerHTML = buildSkeletonTable(14, 14);
        fetch(CONTEXT+"/getTelecallingByDate",{
            method:"POST", headers:{"Content-Type":"application/json"},
            body:JSON.stringify({userId: getEffectiveUserId(), uniqueId:uniqueId, fromDate:range.fromDate, toDate:range.toDate})
        })
        .then(function(r){ return r.json(); })
        .then(function(resp){
            telecallingData = resp.data || [];
            renderTelecallingTable(telecallingData);
        })
        .catch(function(){
            document.getElementById("dynamic-content-container").innerHTML=
                '<div class="empty-state"><i class="fa fa-triangle-exclamation"></i><p>Failed to load data.</p></div>';
        });
    }

    /* ★ MODIFIED — added "SPOC Name" column (3rd position, after Contact) */
    function renderTelecallingTable(list) {
        var c = document.getElementById("dynamic-content-container");
        if (!list||!list.length) {
            c.innerHTML='<div class="empty-state"><i class="fa fa-phone-slash"></i><p>No telecalling entries found for this date.</p></div>'; return;
        }
        var h = "<table class='table clean-table'><thead><tr>";
        ["S.No","Date","Company","SPOC Name","Contact","Designation","Type of Call","DM","Level of DM","Status","Interest","Next Follow Up","Remarks","Actions"]
            .forEach(function(hh){ h+="<th>"+hh+"</th>"; });
        h += "</tr></thead><tbody>";
        list.forEach(function(r,i){
            h += "<tr style='cursor:pointer;' onclick='openTelecallingDetailModal("+r.id+")'>";
            h += "<td>"+(i+1)+".</td>";
            h += "<td style='white-space:nowrap;'>"+(r.date||"—")+"</td>";
            // h += "<td><strong>"+(r.companyName||"—")+"</strong></td>";
            h += "<td><strong title='"+escAttr(r.companyName||"")+"'>"+(r.companyName ? escapeHtml(r.companyName.length > 40 ? r.companyName.substring(0,40)+"..." : r.companyName) : "—")+"</strong></td>";
            h += "<td>"+spocBadge(r.userId)+"</td>";
            h += "<td>"+(r.contactPerson? escapeHtml(r.contactPerson) : "—")+"</td>";
            /* ★ NEW */
            // h += "<td>"+spocBadge(r.userId)+"</td>";
            h += "<td style='color:#64748b;font-size:12px;'>"+(r.designation? escapeHtml(r.designation) : "—")+"</td>";
            h += "<td>"+(r.typeOfCall ? '<span class="chip" style="background:#e0f2fe;color:#0369a1;">'+r.typeOfCall+'</span>' : "—")+"</td>";
            h += "<td>"+chip(r.decisionMaker,"yn")+"</td>";
            h += "<td>"+(r.levelOfDM ? '<span class="chip" style="background:#f1f5f9;color:#334155;">'+r.levelOfDM+'</span>' : "—")+"</td>";
            h += "<td>"+(r.status ? '<span class="chip" style="background:#fef9c3;color:#854d0e;">'+r.status+'</span>' : "—")+"</td>";
            h += "<td>"+chip(r.interestCreated,"yn")+"</td>";
            h += "<td style='white-space:nowrap;'>"+(r.nextFollowUpDate||"—")+"</td>";
            // h += "<td style='max-width:200px;white-space:normal;font-size:12px;'>"+(r.remarks||"—")+"</td>";
            h += "<td><span title='"+escAttr(r.remarks||"")+"'>"+(r.remarks ? escapeHtml(r.remarks.length > 30 ? r.remarks.substring(0,30)+"..." : r.remarks) : "—")+"</span></td>";
            h += "<td style='text-align:center;'><button class='alert-menu-btn' data-id='"+r.id+"' onclick='event.stopPropagation();openActionMenu(this,"+r.id+")'>&#8942;</button></td>";
            h += "</tr>";
        });
        h += "</tbody></table>";
        c.innerHTML = h;
    }

    window.tcHandleStatusChange = function() {
        var status = document.getElementById("tc_status").value;
        var icEl   = document.getElementById("tc_interestCreated");
        var icWrap = icEl.closest(".form-group");
        if (status === "Did not pick") { icWrap.style.display="none"; icEl.value=""; }
        else if (status === "Not interested")  { icWrap.style.display=""; icEl.value="No"; }
        else if (status === "Meeting fixed" || status === "Demo scheduled") { icWrap.style.display=""; icEl.value="Yes"; }
        else { icWrap.style.display=""; icEl.value=""; }
    };

    window.saveTelecalling = function () {
        var msg = document.getElementById("tc-modal-msg");
        var companyName     = document.getElementById("tc_companyName").value.trim();
        var contactMeta     = selectedContactMeta("tc_contactPerson");
        var accountMasterId = toLongOrNull(document.getElementById("tc_accountMasterId").value);
        if (!companyName) { msg.style.color="red"; msg.innerHTML="Please select a company."; return; }
        var status = document.getElementById("tc_status").value;
        var interestCreated = document.getElementById("tc_interestCreated").value;
        if (status === "Answered" && !interestCreated) {
            msg.style.color="red"; msg.innerHTML="Please select Interest Created for Answered calls."; return;
        }

        var fd = new FormData();
        fd.append("userId",          userId);
        fd.append("uniqueId",        uniqueId);
        fd.append("date",            isoToDMY(document.getElementById("tc_date").value));
        fd.append("companyName",     companyName);
        fd.append("accountMasterId", accountMasterId || "");
        fd.append("accountContactId",contactMeta.id  || "");
        fd.append("contactPerson",   contactMeta.name || "");
        fd.append("typeOfCall",      document.getElementById("tc_typeOfCall").value);
        fd.append("decisionMaker",   document.getElementById("tc_decisionMaker").value);
        fd.append("levelOfDM",       document.getElementById("tc_levelOfDM").value);
        fd.append("status",          status);
        fd.append("remarks",         document.getElementById("tc_remarks").value.trim());
        fd.append("interestCreated", interestCreated);
        fd.append("nextFollowUpDate",isoToDMY(document.getElementById("tc_nextFollowUpDate").value));
        fd.append("designation",     document.getElementById("tc_designation").value.trim());
        var recFile = document.getElementById("tc_callRecording").files[0];
        if (recFile) fd.append("callRecording", recFile);

        msg.style.color="#2563eb"; msg.innerHTML="Saving...";
        fetch(CONTEXT+"/saveTelecalling", { method:"POST", body: fd })
        .then(function(r){ return r.json(); })
        .then(function(resp){
            if(resp.status===200){ msg.style.color="green"; msg.innerHTML="Saved!";
                setTimeout(function(){ $("#telecallingModal").modal("hide"); loadTelecallingByDate(); },400); }
            else { msg.style.color="red"; msg.innerHTML=resp.message||"Error saving."; }
        }).catch(function(){ msg.style.color="red"; msg.innerHTML="Something went wrong."; });
    };

