    function openLeadIdentificationEditModal(id) {
        var row=leadIdentificationData.find(function(r){ return r.id==id; });
        if(!row){ alert("Record not found. Reload."); return; }
        document.getElementById("edit_lid_id").value      =row.id;
        document.getElementById("edit_lid_uniqueId").value=row.uniqueId||uniqueId;
        document.getElementById("edit_lid_date").value    =dmyToISO(row.date);
        ["location","buildingSize","noOfTowers","noOfAdditionalLocations","designation","mail","mobile","linkedInURL","nextSteps","remarks"].forEach(function(f){
            var el=document.getElementById("edit_lid_"+f); if(el) el.value=row[f]||"";
        });
        // ["headQuartered","existingProcess","techUsed","meetingScheduled"].forEach(function(f){ document.getElementById("edit_lid_"+f).value=row[f]||""; });
        ["headQuartered","meetingScheduled"].forEach(function(f){
		    document.getElementById("edit_lid_" + f).value = row[f] || "";
		});
		
		// existingProcess + techUsed handled together so the wrap shows correctly
		document.getElementById("edit_lid_existingProcess").value = row.existingProcess || "";
		var editTechWrap = document.getElementById("edit_lid_techUsed_wrap");
		var editTechInp  = document.getElementById("edit_lid_techUsed");
		if (row.existingProcess === "Software") {
		    editTechWrap.style.display = "";
		    editTechInp.value = row.techUsed || "";
		} else {
		    editTechWrap.style.display = "none";
		    editTechInp.value = "";
		}
        document.getElementById("edit_lid_nextFollowUpDate").value=dmyToISO(row.nextFollowUpDate);
        // var master=accountMasterData.find(function(m){ return m.companyName===row.companyName; });
        var master=(accountMasterAllData.length ? accountMasterAllData : accountMasterData).find(function(m){ return m.companyName===row.companyName; });
        var contacts=master?(master.contacts||[]):[];
        _prsContacts["edit_lid"]=contacts;
        document.getElementById("edit_lid_companyName").value   =row.companyName||"";
        document.getElementById("edit_lid_accountMasterId").value=row.accountMasterId||(master?master.id:"");
        document.getElementById("edit_lid_accountContactId").value=row.accountContactId||"";
        var cmpLabel=document.getElementById("edit_lid_cmp_label");
        if(row.companyName){ cmpLabel.textContent=master?companyLabel(master):row.companyName; cmpLabel.classList.remove("placeholder"); }
        else { cmpLabel.textContent="Select Company"; cmpLabel.className="custom-select-trigger-text placeholder"; }
        // vtcSetValue("edit_lid_vtc",row.vertical||"");
        var verticalMap = {
		    "Tech Park":        "Tech Park/Campus",
		    "Hotel":            "FMCG/Hotel/Food Chains",
		    "Hotel/Food Chains":"FMCG/Hotel/Food Chains",
		    "Hospital":         "Hospital",
		    "Universities":     "Institutes/Universities"
		};
		vtcSetValue("edit_lid_vtc", verticalMap[row.vertical] || row.vertical || "");
        prsSetValue("edit_lid_prs",row.spocName||"",contacts,row.accountContactId);
        document.getElementById("edit-lid-modal-msg").innerHTML="";
        document.getElementById("edit_lid_date").setAttribute("max", todayISO());
        $("#editLeadIdentificationModal").modal("show");
    }

    window.updateLeadIdentification = function() {
        var msg=document.getElementById("edit-lid-modal-msg");
        var companyName=document.getElementById("edit_lid_companyName").value.trim();
        var accountMasterId=toLongOrNull(document.getElementById("edit_lid_accountMasterId").value);
        var accountContactId=toLongOrNull(document.getElementById("edit_lid_accountContactId").value);
        if(!companyName){ msg.style.color="red"; msg.innerHTML="Please select a company."; return; }
        var p={
            id:document.getElementById("edit_lid_id").value, uniqueId:document.getElementById("edit_lid_uniqueId").value||uniqueId, userId:userId,
            date:                   isoToDMY(document.getElementById("edit_lid_date").value),
            companyName:            companyName, accountMasterId:accountMasterId, accountContactId:accountContactId,
            location:               document.getElementById("edit_lid_location").value.trim(),
            vertical:               document.getElementById("edit_lid_vertical").value,
            buildingSize:           document.getElementById("edit_lid_buildingSize").value.trim(),
            noOfTowers:             document.getElementById("edit_lid_noOfTowers").value.trim(),
            noOfAdditionalLocations:document.getElementById("edit_lid_noOfAdditionalLocations").value.trim(),
            headQuartered:          document.getElementById("edit_lid_headQuartered").value,
            spocName:               document.getElementById("edit_lid_spocName").value.trim(),
            designation:            document.getElementById("edit_lid_designation").value.trim(),
            mail:                   document.getElementById("edit_lid_mail").value.trim(),
            mobile:                 document.getElementById("edit_lid_mobile").value.trim(),
            linkedInURL:            document.getElementById("edit_lid_linkedInURL").value.trim(),
            existingProcess:        document.getElementById("edit_lid_existingProcess").value,
            techUsed:               document.getElementById("edit_lid_techUsed").value,
            meetingScheduled:       document.getElementById("edit_lid_meetingScheduled").value,
            nextFollowUpDate:       isoToDMY(document.getElementById("edit_lid_nextFollowUpDate").value),
            nextSteps:              document.getElementById("edit_lid_nextSteps").value.trim(),
            remarks:                document.getElementById("edit_lid_remarks").value.trim()
        };
        msg.style.color="#2563eb"; msg.innerHTML="Updating...";
        if (document.getElementById("edit_lid_existingProcess").value === "Software" &&
        	    !document.getElementById("edit_lid_techUsed").value.trim()) {
        	    msg.style.color = "red";
        	    msg.innerHTML   = "Please enter the software name.";
        	    return;
        	}
        fetch(CONTEXT+"/editLeadIdentification",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(p)})
        .then(function(r){ return r.json(); })
        .then(function(resp){
            if(resp.status===200){ msg.style.color="green"; msg.innerHTML="Updated!";
                setTimeout(function(){ $("#editLeadIdentificationModal").modal("hide"); loadLeadIdentificationByDate(); },400); }
            else { msg.style.color="red"; msg.innerHTML=resp.message||"Error updating."; }
        }).catch(function(){ msg.style.color="red"; msg.innerHTML="Something went wrong."; });
    };

    function deleteLeadIdentification(id) {
        if(!confirm("Delete this lead identification entry?")) return;
        fetch(CONTEXT+"/deleteLeadIdentification?id="+id+"&uniqueId="+encodeURIComponent(uniqueId),{method:"POST"})
        .then(function(r){ return r.json(); })
        .then(function(resp){ if(resp.status===200) loadLeadIdentificationByDate(); else alert(resp.message||"Could not delete."); })
        .catch(function(){ alert("Something went wrong."); });
    }

    function addMenuBtn(menu, text, isDanger, handler) {
        var btn=document.createElement("button"); btn.innerHTML=text;
        if(isDanger) btn.classList.add("danger");
        btn.onclick=function(e){ e.stopPropagation(); document.querySelectorAll(".custom-action-menu").forEach(function(m){ m.remove(); }); handler(); };
        menu.appendChild(btn);
    }

    /* ─── Search ─── */
    var _amSearchTimer = null;

    document.getElementById("dynamic-search-input").addEventListener("input", function () {
        var term = this.value.toLowerCase().trim();

        if (activeTab === "accountmaster") {
            /* ── Server-side search with debounce ── */
            clearTimeout(_amSearchTimer);
            _amSearchTimer = setTimeout(function () {
                loadAccountMasters(1);  // reset to page 1 on every new search
            }, 350);
            return;
        }

        if (activeTab === "telecalling") {
            if (!term) { renderTelecallingTable(telecallingData); return; }
            renderTelecallingTable(telecallingData.filter(function (r) {
                var spocName = r.userId ? (userNameMap[String(r.userId)] || "") : "";
                return (r.companyName  && r.companyName.toLowerCase().includes(term))  ||
                       (r.contactPerson && r.contactPerson.toLowerCase().includes(term)) ||
                       (r.status        && r.status.toLowerCase().includes(term))        ||
                       spocName.toLowerCase().includes(term)                             ||
                       (r.remarks       && r.remarks.toLowerCase().includes(term));
            }));
        }

        if (activeTab === "linkedin") {
            if (!term) { renderLinkedInTable(linkedInData); return; }
            renderLinkedInTable(linkedInData.filter(function (r) {
                var spocName = r.userId ? (userNameMap[String(r.userId)] || "") : "";
                return (r.companyName  && r.companyName.toLowerCase().includes(term))  ||
                       (r.personName   && r.personName.toLowerCase().includes(term))   ||
                       (r.activityType && r.activityType.toLowerCase().includes(term)) ||
                       spocName.toLowerCase().includes(term)                           ||
                       (r.remarks      && r.remarks.toLowerCase().includes(term));
            }));
        }

        if (activeTab === "leadidentification") {
            if (!term) { renderLeadIdentificationTable(leadIdentificationData); return; }
            renderLeadIdentificationTable(leadIdentificationData.filter(function (r) {
                var spocName = r.userId ? (userNameMap[String(r.userId)] || "") : "";
                return (r.companyName && r.companyName.toLowerCase().includes(term)) ||
                       (r.spocName    && r.spocName.toLowerCase().includes(term))    ||
                       (r.location    && r.location.toLowerCase().includes(term))    ||
                       spocName.toLowerCase().includes(term)                         ||
                       (r.remarks     && r.remarks.toLowerCase().includes(term));
            }));
        }
    });
    
    document.getElementById("tc_callRecording").addEventListener("change", function() {
        var info = document.getElementById("tc_callRecording_info");
        var nameEl = document.getElementById("tc_callRecording_name");
        if (this.files && this.files[0]) {
            info.style.display = "block";
            nameEl.textContent = this.files[0].name + " (" + (this.files[0].size/1024).toFixed(1) + " KB)";
        } else {
            info.style.display = "none";
            nameEl.textContent = "";
        }
    });

