  document.addEventListener('click', function (event) {
    const anchor = event.target && event.target.closest ? event.target.closest('a[href]') : null;
    if (!anchor || event.defaultPrevented) return;

    const href = anchor.getAttribute('href') || '';
    if (!href || href === '#') return;

    let url;
    try { url = new URL(href, window.top.location.origin); }
    catch (_) { return; }

    if (url.origin !== window.top.location.origin) return;
    const nextPath = routeMap[url.pathname];
    if (!nextPath) return;

    event.preventDefault();
    event.stopPropagation();

    const nextUrl = nextPath + (url.search || '') + (url.hash || '');
    window.top.history.pushState({}, '', nextUrl);
    window.top.dispatchEvent(new PopStateEvent('popstate'));
  }, true);
