	window.exportDrillToExcel = exportDrillToExcel;

 /* ── LinkedIn drill table ── */
 function renderLinkedInDrillTable(rows) {
	 drillCurrentRows = rows;
     var body = document.getElementById("kpiDrillBody");
     if (!rows.length) {
         body.innerHTML = '<div class="drill-empty"><i class="fa-brands fa-linkedin" style="font-size:36px;"></i><p>No records found for this period.</p></div>';
         return;
     }

     function chip(val) {
         return val
             ? '<span class="drill-chip" style="background:' +
               (val === "Yes" ? "#dcfce7;color:#15803d" : "#fee2e2;color:#b91c1c") + ';">' + escapeHtml(val) + '</span>'
             : '<span style="color:#94a3b8;">—</span>';
     }
     function chipBlue(val) {
         return val
             ? '<span class="drill-chip" style="background:#dbeafe;color:#1d4ed8;">' + escapeHtml(val) + '</span>'
             : '<span style="color:#94a3b8;">—</span>';
     }
     function dash(v) { return v || '<span style="color:#94a3b8;">—</span>'; }

     var h = '<div style="overflow-x:auto;">' +
         '<table class="drill-table"><thead><tr>' +
         '<th>#</th><th>Date</th><th>Company</th><th>Person</th>' +
         '<th>Email</th>' +
         '<th>Activity Type</th><th>Conn. Status</th>' +
         '<th>Msg Sent</th><th>Response</th><th>Interest</th><th>Follow Up Date</th>' +
         '</tr></thead><tbody>';

     rows.forEach(function(r, i) {
         h += '<tr>';
         h += '<td style="color:#94a3b8;font-size:11px;">' + (i+1) + '</td>';
         h += '<td style="white-space:nowrap;">' + dash(r.date) + '</td>';
         h += '<td><strong>' + dash(escapeHtml(r.companyName)) + '</strong></td>';
         // h += '<td>' + dash(r.personName) + '</td>';
         h += '<td>' +
		     dash(escapeHtml(r.personName)) +
		     (r.contactNumber
		         ? '<div style="margin-top:3px;">' +
		           '<a href="tel:' + escAttr(r.contactNumber) + '" ' +
		           'style="display:inline-flex;align-items:center;gap:5px;color:#334155;' +
		           'font-size:11px;font-weight:600;text-decoration:none;">' +
		           '<i class="fa fa-phone" style="font-size:10px;color:var(--green);"></i>' +
		           escapeHtml(r.contactNumber) + '</a></div>'
		         : '') +
		     (safeHref(r.contactLinkedIn)
		         ? '<div style="margin-top:3px;">' +
		           '<a href="' + safeHref(r.contactLinkedIn) + '" target="_blank" ' +
		           'style="display:inline-flex;align-items:center;gap:5px;color:#0077b5;' +
		           'font-size:11px;font-weight:600;text-decoration:none;">' +
		           '<i class="fa-brands fa-linkedin" style="font-size:11px;"></i>' +
		           'LinkedIn</a></div>'
		         : '') +
		     '</td>';
		     h += '<td>' +
		     (r.mailId
		         ? '<a href="mailto:' + escAttr(r.mailId) + '" ' +
		           'style="display:inline-flex;align-items:center;gap:5px;color:#2563eb;' +
		           'font-size:11px;font-weight:600;text-decoration:none;white-space:nowrap;">' +
		           '<i class="fa fa-envelope" style="font-size:10px;color:var(--blue);"></i>' +
		           escapeHtml(r.mailId) + '</a>'
		         : '<span style="color:#94a3b8;">—</span>') +
		     '</td>';
         h += '<td>' + chipBlue(r.activityType) + '</td>';
         h += '<td>' + (r.connectionStatus
             ? '<span class="drill-chip" style="background:#ede9fe;color:#6d28d9;">' + escapeHtml(r.connectionStatus) + '</span>'
             : '<span style="color:#94a3b8;">—</span>') + '</td>';
         h += '<td>' + chip(r.messageSent) + '</td>';
         h += '<td>' + chip(r.responseReceived) + '</td>';
         h += '<td>' + chip(r.interestCreated) + '</td>';
         h += '<td style="white-space:nowrap;">' + dash(r.followUpDate) + '</td>';
         h += '</tr>';
     });

     h += '</tbody></table></div>';
     body.innerHTML = h;
 }

    /* ── Converts yyyy-mm-dd  →  dd-mm-yyyy (backend format) ── */
    function toBackendDate(isoDate) {
        if (!isoDate) return "";
        var parts = isoDate.split("-");
        return parts[2] + "-" + parts[1] + "-" + parts[0];
    }

    /* ── Converts yyyy-mm-dd  →  "20 May 2026" (display) ── */
    function toDisplayDate(isoDate) {
        if (!isoDate) return "—";
        var months = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
        var parts = isoDate.split("-");
        return parseInt(parts[2]) + " " + months[parseInt(parts[1]) - 1] + " " + parts[0];
    }
    
    var currentPeriodMode = "daily";

    function setPeriodMode(mode) {
        currentPeriodMode = mode;
        document.getElementById("toggleDaily").classList.toggle("active", mode === "daily");
        document.getElementById("toggleWeekly").classList.toggle("active", mode === "weekly");
        document.getElementById("toggleMonthly").classList.toggle("active", mode === "monthly");
        syncDateChip();
        fetchDashboard();
    }

    function syncDateChip() {
        var el = document.getElementById("mbDateDisplay");
        if (!el) return;

        if (currentPeriodMode === "daily") {
            var val = document.getElementById("datePicker").value;
            if (!val) return;
            var p = val.split("-");
            el.textContent = p[2] + "-" + p[1] + "-" + p[0];
            updatePeriodLabel(val);
        } else if (currentPeriodMode === "weekly") {
            var val = document.getElementById("datePicker").value;
            if (!val) return;
            var range = getWeekRange(val);
            el.textContent = range.label;
            updatePeriodLabelFromWeek(val);
        } else {
            var val = document.getElementById("monthPicker").value;  /* yyyy-mm */
            if (!val) return;
            var months = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
            var p = val.split("-");
            el.textContent = months[parseInt(p[1]) - 1] + " " + p[0];
            updatePeriodLabelFromMonth(val);
        }
    }

    function getWeekRange(isoDate) {
        var d = new Date(isoDate);
        var day = d.getDay();
        var diffToMon = (day === 0) ? -6 : 1 - day;
        var monday = new Date(d); monday.setDate(d.getDate() + diffToMon);
        var friday = new Date(monday); friday.setDate(monday.getDate() + 4);
        var months = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
        var pad = function(n){ return String(n).padStart(2,"0"); };
        var monStr = pad(monday.getDate()) + "-" + pad(monday.getMonth()+1) + "-" + monday.getFullYear();
        var friStr = pad(friday.getDate()) + "-" + pad(friday.getMonth()+1) + "-" + friday.getFullYear();
        var label = monday.getDate() + " " + months[monday.getMonth()] + " – " + friday.getDate() + " " + months[friday.getMonth()];
        if (monday.getFullYear() !== friday.getFullYear()) label += " " + friday.getFullYear();
        return { monBackend: monStr, friBackend: friStr, label: label, monday: monday, friday: friday };
    }

    function updatePeriodLabelFromWeek(isoDate) {
        var el = document.getElementById("dynamicPeriod");
        if (!el || !isoDate) return;
        var range = getWeekRange(isoDate);
        var today = new Date(); today.setHours(0,0,0,0);
        var mon = range.monday; mon.setHours(0,0,0,0);
        var fri = range.friday; fri.setHours(0,0,0,0);
        if (today >= mon && today <= fri) {
            el.textContent = "This Week";
        } else {
            el.textContent = range.label;
        }
    }

    /* Initialise month picker to current month */
    (function initPickers() {
        var dp = document.getElementById("datePicker");
        var mp = document.getElementById("monthPicker");
        var now = new Date();
        var y = now.getFullYear();
        var m = String(now.getMonth() + 1).padStart(2, "0");
        var d = String(now.getDate()).padStart(2, "0");
        if (dp) dp.value = y + "-" + m + "-" + d;
        if (mp) mp.value = y + "-" + m;
        syncDateChip();
    })();

    /* Listeners */
    document.getElementById("datePicker").addEventListener("change", function () {
        syncDateChip();
        fetchDashboard();
    });

    document.getElementById("monthPicker").addEventListener("change", function () {
        syncDateChip();
        fetchDashboard();
    });
    
    document.getElementById("toggleDaily").addEventListener("click", function () {
        setPeriodMode("daily");
    });

    document.getElementById("toggleWeekly").addEventListener("click", function () {
        setPeriodMode("weekly");
    });

    document.getElementById("toggleMonthly").addEventListener("click", function () {
        setPeriodMode("monthly");
    });

    document.getElementById("mbDateChip").addEventListener("click", function () {
        if (currentPeriodMode === "monthly") {
            document.getElementById("monthPicker").showPicker();
        } else {
            document.getElementById("datePicker").showPicker();
        }
    });

    /* Period badge for monthly mode */
    function updatePeriodLabelFromMonth(yyyyMm) {
        var el = document.getElementById("dynamicPeriod");
        if (!el || !yyyyMm) return;
        var today = new Date();
        var p = yyyyMm.split("-");
        var selYear  = parseInt(p[0]);
        var selMonth = parseInt(p[1]) - 1;
        var months = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];

        var isCurrent = selYear === today.getFullYear() && selMonth === today.getMonth();
        var isLast = (selYear === today.getFullYear() && selMonth === today.getMonth() - 1) ||
                     (today.getMonth() === 0 && selMonth === 11 && selYear === today.getFullYear() - 1);

        el.textContent = isCurrent ? "This Month" : isLast ? "Last Month" : months[selMonth] + " " + selYear;
        el.classList.toggle("current", isCurrent);
    }

    /* ══════════════════════════════════════════
	    1.  LOAD USERS ON PAGE LOAD
	        GET  /sck360/getUsersByDepartment
	        Filter out role === 'CEO'
	 ══════════════════════════════════════════ */
 function loadUsers() {
            var uniqueId = sessionUniqueId || sessionStorage.getItem("uniqueId");
            var selfId   = sessionUserId   || sessionStorage.getItem("userId") || "";
            var dropdown = document.getElementById("userDropdown");
            var menu     = document.getElementById("customDropdownMenu");
            var label    = document.getElementById("customSelectedLabel");

            if (!dropdown || !menu || !label) {
                console.error("Sales Individual: user selector elements are missing.");
                return;
            }

            function normalizeUsers(raw) {
                if (!Array.isArray(raw)) return [];
                return raw.map(function (u) {
                    if (!u || typeof u !== "object") return null;
                    var id = u.userId != null ? u.userId :
                             u.id != null ? u.id :
                             u.employeeId != null ? u.employeeId :
                             u.userID != null ? u.userID :
                             u.empId != null ? u.empId : null;
                    if (id == null || String(id).trim() === "") return null;
                    return {
                        userId: id,
                        uniqueId: u.uniqueId || u.uniqueID || uniqueId,
                        name: u.name || u.userName || u.fullName || u.employeeName || String(id),
                        role: u.role || u.roleName || u.roleType || u.designation || u.jobTitle || "Sales",
                        department: u.department || u.departmentName || "Sales",
                        profilePictureUrl: u.profilePictureUrl || u.profilePicture || u.profileImage || ""
                    };
                }).filter(Boolean);
            }

            function readUserArray(res) {
                if (!res) return [];
                var candidates = [
                    res.data,
                    res.users,
                    res.records,
                    res.userList,
                    res.data && res.data.users,
                    res.data && res.data.records,
                    res.data && res.data.data,
                    res.result,
                    res.result && res.result.data,
                    res.payload,
                    res.payload && res.payload.data
                ];
                for (var i = 0; i < candidates.length; i++) {
                    if (Array.isArray(candidates[i])) return normalizeUsers(candidates[i]);
                }
                return normalizeUsers(candidates.find(function (v) { return Array.isArray(v); }) || []);
            }

            function getSessionFallbackUser() {
                var fallbackId = selfId || "";
                var fallbackUniqueId = uniqueId || "";
                var name = sessionStorage.getItem("name") || "";
                var role = sessionStorage.getItem("role") || "";
                try {
                    var topDoc = window.top && window.top.document;
                    var topName = topDoc && topDoc.getElementById("ptName");
                    var topRole = topDoc && topDoc.getElementById("ptRole");
                    if (topName && topName.textContent.trim()) name = topName.textContent.trim();
                    if (topRole && topRole.textContent.trim()) role = topRole.textContent.trim();
                } catch (_) {}
                if (!fallbackId || !fallbackUniqueId || /^react-demo/i.test(fallbackId) || /^react-demo/i.test(fallbackUniqueId) || !name || name.trim().toLowerCase() === "user") return null;
                return { userId: fallbackId, uniqueId: fallbackUniqueId, name: name, role: role || "Sales", department: "Sales", profilePictureUrl: "" };
            }

            function showSelectedUser(u, locked) {
                userNameMap[String(u.userId)] = u.name;
                buildCustomDropdown([u], u, dropdown, menu, !!locked);
                selectDropdownUser(u, dropdown, menu);
                label.textContent = u.name + " (" + u.role + ")";
                setTopAvatarFromUser(u);
            }

            function showUsers(users) {
                if (!users.length) return false;
                userNameMap = {};
                users.forEach(function (u) { userNameMap[String(u.userId)] = u.name; });

                /* Keep the original executive-role exclusion, but do NOT lock
                   ordinary sales users to their own profile. The Sales Individual
                   selector is expected to let the user choose from the available
                   Sales roster. */
                var EXEC_ROLES = ["CEO", "CTO", "COO"];
                var eligible = users.filter(function (u) {
                    return EXEC_ROLES.indexOf(String(u.role || "").toUpperCase()) === -1;
                });
                if (!eligible.length) eligible = users;

                /* The React shell may know the logged-in user even when the
                   Sales/DMR dummy roster does not. Keep that user in the selector
                   so the visible selection and the dashboard identity stay aligned. */
                var preferred = eligible.find(function (u) {
                    return String(u.userId) === String(selfId);
                });
                if (!preferred && immediate && immediate.name) {
                    var immediateExists = eligible.some(function (u) {
                        return String(u.userId) === String(immediate.userId);
                    });
                    if (!immediateExists) eligible.unshift(immediate);
                    preferred = immediate;
                }
                preferred = preferred || eligible[0];

                /* Build the complete selectable list and preselect the current
                   session user when it is present. The chevron remains enabled. */
                buildCustomDropdown(eligible, preferred, dropdown, menu, false);
                selectDropdownUser(preferred, dropdown, menu);
                label.textContent = preferred.name + " (" + preferred.role + ")";
                setTopAvatarFromUser(preferred);
                return true;
            }

            /* Never leave the control visually stuck on Loading. */
            var immediate = getSessionFallbackUser();
            label.textContent = immediate ? (immediate.name + " (" + immediate.role + ")") : "No user loaded";
            if (immediate) { try { setTopAvatarFromUser(immediate); } catch (_) {} }

            /* Prefer the combined Sales/DMR roster endpoint. Fall back to the
               JSP-compatible basic-details route. Neither route should be capable
               of permanently leaving the selector on Loading. */
            var endpoints = [
                "/sck360/getAllUsers",
                "/sck360/getUsersBasicDetails"
            ];
            var endpointIndex = 0;

            function tryNextRosterEndpoint(lastError) {
                if (endpointIndex >= endpoints.length) {
                    console.warn("Sales Individual user roster unavailable:", lastError);
                    if (immediate) {
                        showSelectedUser(immediate, true);
                        var fallbackDownload = document.getElementById("mbDownloadWrap");
                        if (fallbackDownload) fallbackDownload.style.display = "block";
                        fetchDashboard();
                    } else {
                        if (dropdown) { dropdown.innerHTML = '<option value="">Live users unavailable</option>'; dropdown.value = ""; dropdown.disabled = true; }
                        if (menu) menu.innerHTML = '<div class="mb-dropdown-placeholder">Live user data is unavailable.</div>';
                        label.textContent = "No user loaded";
                        var topAvatar = document.getElementById("topUserAvatar"); if (topAvatar) topAvatar.textContent = "—";
                        var fallbackDownload = document.getElementById("mbDownloadWrap"); if (fallbackDownload) fallbackDownload.style.display = "none";
                        resetSalesIndividualKpis("Unable to load live users from the server. No KPI data is displayed until the user and API data are available.");
                    }
                    return;
                }

                var endpoint = endpoints[endpointIndex++];
                var controller = typeof AbortController !== "undefined" ? new AbortController() : null;
                var timer = controller ? setTimeout(function () { controller.abort(); }, 4000) : null;

                fetch(endpoint, {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({ uniqueId: uniqueId || "" }),
                    signal: controller ? controller.signal : undefined
                })
                .then(function (res) {
                    if (!res.ok) throw new Error("HTTP " + res.status + " from " + endpoint);
                    return res.json();
                })
                .then(function (res) {
                    if (timer) clearTimeout(timer);
                    var users = readUserArray(res);
                    if (!showUsers(users)) throw new Error("No usable users returned from " + endpoint);
                    var downloadWrap = document.getElementById("mbDownloadWrap");
                    if (downloadWrap) downloadWrap.style.display = "block";
                    fetchDashboard();
                })
                .catch(function (err) {
                    if (timer) clearTimeout(timer);
                    tryNextRosterEndpoint(err);
                });
            }

            tryNextRosterEndpoint();
        }

	 function buildCustomDropdown(users, forcedUser, dropdown, menu, disabled) {
		    /* Rebuild hidden <select> */
		    dropdown.innerHTML = "";
		    users.forEach(function (u) {
		        var opt = document.createElement("option");
		        opt.value = JSON.stringify({
		            userId: u.userId, uniqueId: u.uniqueId,
		            name: u.name, role: u.role,
		            profilePictureUrl: u.profilePictureUrl || ""
		        });
		        opt.textContent = u.name + " (" + u.role + ")";
		        dropdown.appendChild(opt);
		    });

		    /* Rebuild custom menu */
		    menu.innerHTML = "";
		    users.forEach(function (u, idx) {
		        var item = document.createElement("div");
		        item.className = "mb-dropdown-item" + (idx === 0 ? " active" : "");
		        item.dataset.value = JSON.stringify({
		            userId: u.userId, uniqueId: u.uniqueId,
		            name: u.name, role: u.role,
		            profilePictureUrl: u.profilePictureUrl || ""
		        });

		        /* Avatar in dropdown row */
		        var avDiv = document.createElement("div");
		        avDiv.className = "mb-dropdown-avatar";
		        var initials = (u.name || "--").split(" ")
		            .map(function (w) { return w[0] || ""; })
		            .join("").substring(0, 2).toUpperCase();

		        if (u.profilePictureUrl) {
		            var servedUrl = CONTEXT + "/sck360/profilePicture?uniqueId="
		                + encodeURIComponent(u.uniqueId || "")
		                + "&userId=" + encodeURIComponent(u.userId || "")
		                + "&t=" + Date.now();
		            var img = document.createElement("img");
		            img.src = servedUrl;
		            img.alt = initials;
		            img.onerror = (function(el, txt) {
		                return function() { el.innerHTML = ""; el.textContent = txt; };
		            })(avDiv, initials);
		            avDiv.appendChild(img);
		        } else {
		            avDiv.textContent = initials;
		        }

		        var infoDiv = document.createElement("div");
		        infoDiv.innerHTML =
		            '<div class="mb-dropdown-name">' + escapeHtml(u.name) + '</div>' +
		            '<div class="mb-dropdown-role">' + escapeHtml(u.role || "") + '</div>';

		        item.appendChild(avDiv);
		        item.appendChild(infoDiv);

		        if (!disabled) {
		            item.addEventListener("click", function () {
		                selectDropdownUser(u, dropdown, menu);
		                closeCustomDropdown();
		                fetchDashboard();
		            });
		        }

		        menu.appendChild(item);
		    });

		    /* If disabled (single user), don't show chevron or allow open */
		    if (disabled) {
		        var chevron = document.getElementById("customDropdownChevron");
		        if (chevron) chevron.style.display = "none";
		        var display = document.getElementById("customSelectedDisplay");
		        if (display) display.style.cursor = "default";

		        /* Show first user label */
		        if (users[0]) {
		            document.getElementById("customSelectedLabel").textContent =
		                users[0].name + " (" + users[0].role + ")";
		            /* pre-select in hidden select */
		            dropdown.selectedIndex = 0;
		        }
		    }
		}

		function selectDropdownUser(u, dropdown, menu) {
		    /* Update hidden select */
		    var valStr = JSON.stringify({
		        userId: u.userId, uniqueId: u.uniqueId,
		        name: u.name, role: u.role,
		        profilePictureUrl: u.profilePictureUrl || ""
		    });
		    for (var i = 0; i < dropdown.options.length; i++) {
		        try {
		            var opt = JSON.parse(dropdown.options[i].value);
		            if (String(opt.userId) === String(u.userId)) {
		                dropdown.selectedIndex = i;
		                break;
		            }
		        } catch(e) {}
		    }

		    /* Update label */
		    document.getElementById("customSelectedLabel").textContent =
		        u.name + " (" + u.role + ")";

		    /* Mark active item */
		    if (menu) {
		        menu.querySelectorAll(".mb-dropdown-item").forEach(function (el) {
		            el.classList.remove("active");
		            try {
		                var v = JSON.parse(el.dataset.value);
		                if (String(v.userId) === String(u.userId)) el.classList.add("active");
		            } catch(e) {}
		        });
		    }

		    /* Update top avatar */
		    setTopAvatarFromUser(u);
		}

		function setTopAvatarFromUser(u) {
		    var avatarEl = document.getElementById("topUserAvatar");
		    if (!avatarEl) return;
		    var initials = (u.name || "--").split(" ")
		        .map(function (w) { return w[0] || ""; })
		        .join("").substring(0, 2).toUpperCase();

		    avatarEl.innerHTML = "";
		    if (u.profilePictureUrl) {
		        var servedUrl = CONTEXT + "/sck360/profilePicture?uniqueId="
		            + encodeURIComponent(u.uniqueId || "")
		            + "&userId=" + encodeURIComponent(u.userId || "")
		            + "&t=" + Date.now();
		        var img = document.createElement("img");
		        img.src = servedUrl;
		        img.alt = initials;
		        img.style.cssText = "width:100%;height:100%;object-fit:cover;border-radius:50%;display:block;";
		        img.onerror = (function(el, txt) {
		            return function() { el.innerHTML = ""; el.textContent = txt; };
		        })(avatarEl, initials);
		        avatarEl.appendChild(img);
		    } else {
		        avatarEl.textContent = initials;
		    }
		}

		/* ── Toggle open/close ── */
		document.getElementById("customSelectedDisplay").addEventListener("click", function () {
		    var menu    = document.getElementById("customDropdownMenu");
		    var chevron = document.getElementById("customDropdownChevron");
		    var isOpen  = menu.classList.contains("open");
		    if (isOpen) {
		        menu.classList.remove("open");
		        if (chevron) chevron.style.transform = "";
		    } else {
		        menu.classList.add("open");
		        if (chevron) chevron.style.transform = "rotate(180deg)";
		    }
		});

		function closeCustomDropdown() {
		    var menu    = document.getElementById("customDropdownMenu");
		    var chevron = document.getElementById("customDropdownChevron");
		    if (menu)    menu.classList.remove("open");
		    if (chevron) chevron.style.transform = "";
		}

		/* Close on outside click */
		document.addEventListener("click", function (e) {
		    var wrap = document.getElementById("customUserSelect");
		    if (wrap && !wrap.contains(e.target)) closeCustomDropdown();
		});


    /* ══════════════════════════════════════════
       2.  FETCH DASHBOARD  — auto-triggered on dropdown/date change
    ══════════════════════════════════════════ */
    function fetchDashboard() {
        var dropdown = document.getElementById("userDropdown");
        var loader   = document.getElementById("loadingIndicator");

        /* Need user selected */
        if (!dropdown.value) return;

        /* Parse selected user */
        var user = JSON.parse(dropdown.value);
        selectedUserId   = user.userId;
        selectedUniqueId = user.uniqueId;
        selectedUserName = user.name;

        /* ── Build date/backendDate based on current mode ── */
        var isoDate, backendDate, displayDate;

        if (currentPeriodMode === "daily") {
            isoDate     = document.getElementById("datePicker").value;
            if (!isoDate) return;
            backendDate = toBackendDate(isoDate);
            displayDate = toDisplayDate(isoDate);
            updatePeriodLabel(isoDate);
        } else if (currentPeriodMode === "weekly") {
            isoDate     = document.getElementById("datePicker").value;
            if (!isoDate) return;
            backendDate = toBackendDate(isoDate);
            var range   = getWeekRange(isoDate);
            displayDate = range.label;
            updatePeriodLabelFromWeek(isoDate);
        } else {
            var mv = document.getElementById("monthPicker").value;  /* yyyy-mm */
            if (!mv) return;
            isoDate     = mv + "-01";
            backendDate = mv;
            var months  = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
            var mp      = mv.split("-");
            displayDate = months[parseInt(mp[1]) - 1] + " " + mp[0];
            updatePeriodLabelFromMonth(mv);
        }

        if (loader) loader.classList.add("visible");

        /* Update top bar immediately */
        updateTopBar(user.name, user.role, displayDate, user.profilePictureUrl || "");
        
        var kpiTitle = document.querySelector("#kpiCardsRow").previousElementSibling
		        .querySelector(".dash-section-title");
		if (kpiTitle) kpiTitle.textContent =
		currentPeriodMode === "daily" ? "Today's Activity KPIs" : currentPeriodMode === "weekly" ? "Weekly Activity KPIs" : "Monthly Activity KPIs";

        fetch(SALES + "/getMyPerformanceDashboard", {
            method:  "POST",
            headers: { "Content-Type": "application/json" },
            body:    JSON.stringify({
                userId:      selectedUserId,
                uniqueId:    selectedUniqueId,
                date:        backendDate,
                periodMode:  currentPeriodMode   /* "daily" or "monthly" — backend can use this */
            })
        })
        .then(function (res) { if (!res.ok) throw new Error("HTTP " + res.status); return res.json(); })
        .then(function (res) {
            if (loader) loader.classList.remove("visible");
            if (!res || Number(res.status) !== 200 || !res.data || !res.data.todayKpi || typeof res.data.todayKpi !== "object") {
                throw new Error((res && res.message) || "No live KPI data was returned");
            }
            var kpi = res.data.todayKpi;
            applyKpiCards(kpi, kpi.workingDays);
            updateKpiDate(displayDate);
            showSalesIndividualNotice("Live KPI response received. Invoicing, activity feed, alerts and leaderboard sections are not connected to live endpoints in this frontend build; demo figures have been removed.");

            // Show working days count in weekly/monthly mode
            if ((currentPeriodMode === "monthly" || currentPeriodMode === "weekly") && kpi.workingDays) {
                var kpiDateEl = document.getElementById("kpiDate");
                if (kpiDateEl) {
                    kpiDateEl.textContent = displayDate;
                        // displayDate + "  ·  " + kpi.workingDays + " working days";
                }
            }
        })
        .catch(function (err) {
            if (loader) loader.classList.remove("visible");
            console.warn("Dashboard fetch failed:", err);
            resetSalesIndividualKpis("Could not load live Sales Individual data. Achieved values are unavailable until the backend responds; sample values are disabled.");
        });
    }
    
    function updatePeriodLabel(isoDate) {
        var el = document.getElementById("dynamicPeriod");
        if (!el || !isoDate) return;

        var selected = new Date(isoDate);
        var today    = new Date();
        var months   = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];

        var isCurrent = selected.getFullYear() === today.getFullYear() &&
                        selected.getMonth()    === today.getMonth();

        var label;
        if (isCurrent) {
            label = "This Month";
        } else if (
            (selected.getFullYear() === today.getFullYear() && selected.getMonth() === today.getMonth() - 1) ||
            (today.getMonth() === 0 && selected.getMonth() === 11 && selected.getFullYear() === today.getFullYear() - 1)
        ) {
            label = "Last Month";
        } else {
            label = months[selected.getMonth()] + " " + selected.getFullYear();
        }

        el.textContent = label;
        el.classList.toggle("current", isCurrent);
    }

    /* Wire up auto-fetch on both controls */
    // document.getElementById("userDropdown").addEventListener("change", fetchDashboard);
    document.getElementById("datePicker").addEventListener("change", fetchDashboard);

    /* ══════════════════════════════════════════
       3.  UPDATE TOP BAR
    ══════════════════════════════════════════ */
    function updateTopBar(name, role, displayDate, profilePictureUrl) {
    	console.log("profilePictureUrl =", profilePictureUrl);
        var nameEl   = document.getElementById("topUserName");
        var roleEl   = document.getElementById("topUserRole");
        var avatarEl = document.getElementById("topUserAvatar");
        var dateEl   = document.getElementById("topDate");
        var updEl    = document.getElementById("topUpdated");
        var kpiDateEl = document.getElementById("kpiDate");

        if (nameEl)   nameEl.textContent   = name || "—";
        if (roleEl)   roleEl.textContent   = role || "Sales Executive";
        if (avatarEl) {
            var initials = (name || "--").split(" ")
                .map(function (w) { return w[0] || ""; })
                .join("").substring(0, 2).toUpperCase();

            avatarEl.innerHTML = "";
            if (profilePictureUrl) {
                var servedUrl = CONTEXT + "/sck360/profilePicture?uniqueId="
                    + encodeURIComponent(selectedUniqueId || "")
                    + "&userId=" + encodeURIComponent(selectedUserId || "")
                    + "&t=" + Date.now();
                var img = document.createElement("img");
                img.src = servedUrl;
                img.alt = initials;
                img.style.cssText = "width:100%;height:100%;object-fit:cover;border-radius:50%;display:block;";
                img.onerror = (function(el, txt) {
                    return function() { el.innerHTML = ""; el.textContent = txt; };
                })(avatarEl, initials);
                avatarEl.appendChild(img);
            } else {
                avatarEl.textContent = initials;
            }
        }
        if (dateEl)   dateEl.textContent   = displayDate;
        if (kpiDateEl) kpiDateEl.textContent = displayDate;

        var now  = new Date();
        var h    = now.getHours();
        var min  = now.getMinutes();
        var ampm = h >= 12 ? "PM" : "AM";
        h = h % 12 || 12;
        /* if (updEl) updEl.textContent =
            "Last updated: " + h + ":" + (min < 10 ? "0" + min : min) + " " + ampm + "  🔄"; */
    }

    function updateKpiDate(displayDate) {
        var el = document.getElementById("kpiDate");
        if (el) el.textContent = displayDate;
    }

    /* ══════════════════════════════════════════
       4.  APPLY KPI DATA TO CARDS
    ══════════════════════════════════════════ */
    function applyKpiCards(kpi, workingDays) {
        workingDays = numberValue(workingDays);
        var TARGETS = DAILY_TARGETS;

        /* Helper: compute % capped at 100 for bar width, uncapped for display */
        function pct(achieved, target) {
            if (target == null || !isFinite(Number(target)) || Number(target) <= 0) return null;
            return Math.round((achieved / Number(target)) * 100);
        }

        /* Helper: badge label + CSS class based on % */
        function pillInfo(p) {
		    if (p >= 100) return { label: "Target Met",  cls: "green"  };
		    if (p >= 80)  return { label: "Partial",     cls: "orange" };
		    return              { label: "Below Target", cls: "red"    };
		}

        /* Helper: update a single KPI card */
        function updateCard(ids, achieved, target) {
            if (achieved == null || achieved === "" || !isFinite(Number(achieved))) {
                setText(ids.achieved, "—"); setText(ids.pct, "—"); setBar(ids.bar, 0, ""); setPill(ids.pill, "Unavailable", "neutral");
                if (ids.sub) setText(ids.sub, "Live data unavailable");
                return;
            }
            achieved = Number(achieved);
            if (target == null || !isFinite(Number(target)) || Number(target) <= 0) {
                setText(ids.achieved, achieved);
                setText(ids.pct, "—");
                setBar(ids.bar, 0, "");
                setPill(ids.pill, "Target unavailable", "neutral");
                if (ids.sub) setText(ids.sub, "Target data unavailable from API");
                return;
            }
		    var p    = pct(achieved, target);   
		    var barW = Math.min(p, 100);        
		    var pill = pillInfo(p);
		    var remaining = Math.max(target - achieved, 0);
		
		    var barColor = pill.cls === "green"
		        ? "linear-gradient(90deg,var(--green-light),var(--green))"
		        : pill.cls === "orange"
		            ? "linear-gradient(90deg,#fb923c,#f59e0b)"
		            : "linear-gradient(90deg,#f87171,#ef4444)";
		
		            setText(ids.achieved, achieved);
		            setText(ids.pct,      p + "%");
		            setBar(ids.bar, barW, barColor);
		            setPill(ids.pill, pill.label, pill.cls);
		            
		            var achievedEl = document.getElementById(ids.achieved);
		            if (achievedEl) {
		                achievedEl.style.color = pill.cls === "green"
		                    ? "var(--green)"
		                    : pill.cls === "orange"
		                        ? "var(--orange)"
		                        : "var(--red)";
		            }

		            // ✅ ADD THIS TOO — fixes the big % text color
		            var pctEl = document.getElementById(ids.pct);
		            if (pctEl) {
		                pctEl.className = "kpi-pct-big " + pill.cls;
		            }
		            
		    if (ids.sub) setText(ids.sub,
		        remaining > 0 ? remaining + " remaining" : "Target achieved ✓");
		}

        /* ── Totals for strip ── */
        function liveCount(key) {
            if (!Object.prototype.hasOwnProperty.call(kpi, key) || kpi[key] === null || kpi[key] === "") return null;
            var n = Number(kpi[key]); return isFinite(n) ? n : null;
        }
        var totalCalls  = liveCount("totalCalls");
        var newCalls    = liveCount("newCalls");
        var existing    = liveCount("existingCalls");
        var dm          = liveCount("decisionMakers");
        var interests   = liveCount("interestsCreated");
        var liConn      = liveCount("linkedInConnections");
        var liMsg       = liveCount("personalisedMessages");
        var liFollowUp  = liveCount("linkedInFollowUps");
        var liTotal     = liveCount("linkedInInteractions");
        var cm          = liveCount("clientMeetings");
        
        function pctCapped(achieved, target) {
            if (target == null || !isFinite(Number(target)) || Number(target) <= 0) return null;
            return Math.min(Math.round((achieved / Number(target)) * 100), 100);
        }

        var scoreInputs = [totalCalls, dm, interests, liConn, liMsg, liFollowUp, newCalls];
        var targetKeys = ["totalCalls", "decisionMakers", "interestsCreated", "linkedInConnections", "personalisedMessages", "linkedInFollowUps"];
        var targetsAvailable = targetKeys.every(function(key) { return TARGETS[key] != null && isFinite(Number(TARGETS[key])) && Number(TARGETS[key]) > 0; });
        var score = null;
        if (targetsAvailable && scoreInputs.every(function(v){ return v != null; })) {
            var scoreRaw =
                (pctCapped(totalCalls, TARGETS.totalCalls)           * 0.20) +
                (pctCapped(dm,         TARGETS.decisionMakers)       * 0.20) +
                (pctCapped(interests,  TARGETS.interestsCreated)     * 0.20) +
                (pctCapped(liConn,     TARGETS.linkedInConnections)  * 0.15) +
                (pctCapped(liMsg,      TARGETS.personalisedMessages) * 0.10) +
                (pctCapped(liFollowUp, TARGETS.linkedInFollowUps)    * 0.10) +
                (pctCapped(newCalls,   Math.round(TARGETS.totalCalls * 0.5)) * 0.05);
            score = Math.min(Math.round(scoreRaw), 100);
        }

        /* Ring */
        var ringCircle = document.getElementById("kpiRingCircle");
        if (ringCircle) {
            var offset = score == null ? 188.5 : (188.5 - (score / 100) * 188.5).toFixed(1);
            ringCircle.setAttribute("stroke-dashoffset", offset);
            ringCircle.style.stroke = score == null ? "#cbd5e1" : "";
        }
        setText("kpiRingPct", score == null ? "—" : score + "%");
        setText("kpiScore",   score == null ? "—" : score + "%");

        /* Badge */
        var badgeEl = document.getElementById("kpiBadge");
        if (badgeEl) {
            var b;
            if (score == null) b = { label: "Unavailable", bg: "#e2e8f0", color: "#475569" };
            else if (score >= 95) { b = { label: "Excellent", bg: "#dcfce7", color: "#065f46" }; }
            else if (score >= 90) { b = { label: "Good",      bg: "#dbeafe", color: "#1d4ed8" }; }
            else if (score >= 80) { b = { label: "Average",   bg: "#fef3c7", color: "#92400e" }; }
            else                  { b = { label: "Poor",      bg: "#fee2e2", color: "#991b1b" }; }
            badgeEl.textContent      = b.label;
            badgeEl.style.background = b.bg;
            badgeEl.style.color      = b.color;
        }

        /* Score card: if inputs needed for the score are missing, keep it unavailable. */
        var scorePillInfo = score == null ? {label:"Unavailable",cls:"neutral"} : pillInfo(score >= 100 ? 100 : score);
        var scoreBarColor = scorePillInfo.cls === "green"
            ? ""
            : scorePillInfo.cls === "orange"
                ? "linear-gradient(90deg,#fb923c,#f59e0b)"
                : scorePillInfo.cls === "neutral" ? "" : "linear-gradient(90deg,#f87171,#ef4444)";

        setText("scoreAchieved", score == null ? "—" : score + "%");
        setText("scorePct", score == null ? "—" : score + "%");
        setBar("scoreBar", score == null ? 0 : Math.min(score, 100), scoreBarColor);
        setPill("scorePill", scorePillInfo.label, scorePillInfo.cls);

        var scorePctEl = document.getElementById("scorePct");
        if (scorePctEl) scorePctEl.className = "kpi-pct-big " + scorePillInfo.cls;
        var scoreAchievedEl = document.getElementById("scoreAchieved");
        if (scoreAchievedEl) scoreAchievedEl.style.color = score == null ? "#64748b" : scorePillInfo.cls === "green" ? "var(--green)" : scorePillInfo.cls === "orange" ? "var(--orange)" : "var(--red)";
        var diff = score == null ? null : score - 100;
        setText("scoreSub", diff == null ? "Live data unavailable" : diff >= 0 ? "Exceeds target by " + Math.abs(diff) + " points" : "Below target by " + Math.abs(diff) + " points");

        /* Summary strip uses only fields actually returned by the API. */
        setText("stripTotalCalls", totalCalls == null ? "—" : totalCalls);
        setText("stripDmCount", dm == null ? "—" : dm);
        setText("stripInterests", interests == null ? "—" : interests);
        setText("stripLinkedIn", liTotal == null ? "—" : liTotal);
        var callsValuePct = totalCalls == null ? null : pct(totalCalls, TARGETS.totalCalls);
        var liValuePct = liConn == null ? null : pct(liConn, TARGETS.linkedInConnections);
        var callsPct = callsValuePct == null ? null : Math.max(callsValuePct, 0);
        var liPct = liValuePct == null ? null : Math.max(liValuePct, 0);
        setText("stripCallsPct", callsPct == null ? "—" : callsPct + "%");
        setText("stripLinkedInPct", liPct == null ? "—" : liPct + "%");
        setBar("stripCallsBar", callsPct == null ? 0 : Math.min(callsPct, 100), "linear-gradient(90deg,#3b82f6,#2563eb)");
        setBar("stripLinkedInBar", liPct == null ? 0 : Math.min(liPct, 100), "");

        /* ── Total Calls card ── */
        updateCard(
            { achieved: "totalCallsAchieved", pct: "totalCallsPct",
              bar: "totalCallsBar", pill: "totalCallsPill", sub: "totalCallsSub" },
            totalCalls, TARGETS.totalCalls
        );
        ["totalCallsTarget", "dmTarget", "interestTarget", "msgTarget", "fuTarget", "liConnTarget", "cmTarget"].forEach(function(id) {
            setText(id, "—");
        });
        
        setText("totalCallsSub", newCalls == null || existing == null ? "Live data unavailable" : workingDays > 1
            ? "Avg/day · " + newCalls + " New + " + existing + " Existing"
            : newCalls + " New + " + existing + " Existing");

        /* ── Decision Makers ── */
        updateCard(
            { achieved: "dmAchieved", pct: "dmPct",
              bar: "dmBar", pill: "dmPill", sub: "dmSub" },
            dm, TARGETS.decisionMakers
        );

        /* ── Interests Created ── */
        updateCard(
            { achieved: "interestAchieved", pct: "interestPct",
              bar: "interestBar", pill: "interestPill", sub: "interestSub" },
            interests, TARGETS.interestsCreated
        );

        /* ── Personalised Messages ── */
        updateCard(
            { achieved: "msgAchieved", pct: "msgPct",
              bar: "msgBar", pill: "msgPill", sub: "msgSub" },
            liMsg, TARGETS.personalisedMessages
        );

        /* ── LinkedIn Follow Ups ── */
        updateCard(
            { achieved: "fuAchieved", pct: "fuPct",
              bar: "fuBar", pill: "fuPill", sub: "fuSub" },
            liFollowUp, TARGETS.linkedInFollowUps
        );

        /* ── LinkedIn Connections ── */
        updateCard(
            { achieved: "liConnAchieved", pct: "liConnPct",
              bar: "liConnBar", pill: "liConnPill", sub: "liConnSub" },
            liConn, TARGETS.linkedInConnections
        );

        /* ── Client Meetings ── */
        updateCard(
            { achieved: "cmAchieved", pct: "cmPct",
              bar: "cmBar", pill: "cmPill", sub: "cmSub" },
            cm, TARGETS.clientMeetings
        );
    }

    /* ══════════════════════════════════════════
       DOM HELPERS
    ══════════════════════════════════════════ */
    function setText(id, val) {
        var el = document.getElementById(id);
        if (el) el.textContent = val;
    }

    function setBar(id, widthPct, gradient) {
        var el = document.getElementById(id);
        if (!el) return;
        el.style.width = widthPct + "%";
        if (gradient) el.style.background = gradient;
        else          el.style.background = "";   /* keep CSS default (green) */
    }

    function setPill(id, label, cls) {
        var el = document.getElementById(id);
        if (!el) return;
        el.textContent = label;
        el.className   = "kpi-status-pill " + cls;
    }

