    var contactRowCounter = 0;

    window.addContactRow = function (containerId, data) {
        var container = document.getElementById(containerId);
        ++contactRowCounter;
        data = data || {};
        var div = document.createElement("div");
        div.className = "contact-row";
        div.innerHTML =
            '<div class="contact-row-header">' +
                '<span class="contact-row-label">Contact '+getContactNumber(container)+'</span>' +
                '<button type="button" class="btn-remove-contact" onclick="removeContactRow(this)">&#x2715; Remove</button>' +
            '</div>' +
            '<div class="row">' +
                fld6("Person Name","c-personName","text","e.g. John Doe",data.personName||"") +
                fld6("Designation","c-designation","text","e.g. Facility Manager",data.designation||"") +
                fld6("Contact Number","c-contactNumber","text","e.g. 9876543210",data.contactNumber||"") +
                fld6("Mail ID","c-mailId","email","e.g. john@abc.com",data.mailId||"") +
                fld6("LinkedIn","c-linkedIn","text","https://linkedin.com/in/...",data.linkedIn||"") +
                // MODIFIED — CHANGE 1: funnelStatus removed; ADDED — CHANGE 2: levelOfDM added
                '<div class="col-md-3 form-group"><label style="font-size:12px;font-weight:600;color:#475569;text-transform:uppercase;letter-spacing:.05em;margin-bottom:6px;display:block;">Decision Maker</label>' +
                '<select class="form-control c-decisionMaker"><option value="">Select</option>' +
                '<option value="Yes"'+(data.decisionMaker==="Yes"?" selected":"")+'>Yes</option>' +
                '<option value="No"'+(data.decisionMaker==="No"?" selected":"")+'>No</option></select></div>' +
                '<div class="col-md-3 form-group"><label style="font-size:12px;font-weight:600;color:#475569;text-transform:uppercase;letter-spacing:.05em;margin-bottom:6px;display:block;">Level of DM</label>' +
                '<select class="form-control c-levelOfDM"><option value="">Select</option>' +
                '<option value="L1"'+(data.levelOfDM==="L1"?" selected":"")+'>L1</option>' +
                '<option value="L2"'+(data.levelOfDM==="L2"?" selected":"")+'>L2</option>' +
                '<option value="L3"'+(data.levelOfDM==="L3"?" selected":"")+'>L3</option>' +
                /* '<option value="L4"'+(data.levelOfDM==="L4"?" selected":"")+'>L4</option>' +
                '<option value="L5"'+(data.levelOfDM==="L5"?" selected":"")+'>L5</option>' +
                '<option value="L6"'+(data.levelOfDM==="L6"?" selected":"")+'>L6</option>' +
                '<option value="L7"'+(data.levelOfDM==="L7"?" selected":"")+'>L7</option>' +
                '<option value="L8"'+(data.levelOfDM==="L8"?" selected":"")+'>L8</option>' +
                '<option value="L9"'+(data.levelOfDM==="L9"?" selected":"")+'>L9</option>' + */
                '</select></div>' +
            '</div>';
        container.appendChild(div);
        refreshContactLabels(container);
    };

    function fld6(label, cls, type, ph, val) {
        return '<div class="col-md-6 form-group"><label style="font-size:12px;font-weight:600;color:#475569;text-transform:uppercase;letter-spacing:.05em;margin-bottom:6px;display:block;">'+label+'</label>' +
               '<input type="'+type+'" class="form-control '+cls+'" placeholder="'+ph+'" value="'+escAttr(val)+'"></div>';
    }

    window.removeContactRow = function (btn) {
        var row = btn.closest(".contact-row");
        var container = row.parentNode;
        container.removeChild(row);
        refreshContactLabels(container);
    };
    function getContactNumber(c){ return c.querySelectorAll(".contact-row").length+1; }
    function refreshContactLabels(container) {
        container.querySelectorAll(".contact-row").forEach(function(r,i){
            var l = r.querySelector(".contact-row-label"); if(l) l.textContent="Contact "+(i+1);
        });
    }
    function collectContacts(containerId) {
        var rows = document.getElementById(containerId).querySelectorAll(".contact-row");
        var out = [];
        rows.forEach(function(r){
            out.push({
                personName:    r.querySelector(".c-personName").value.trim(),
                designation:   r.querySelector(".c-designation").value.trim(),
                contactNumber: r.querySelector(".c-contactNumber").value.trim(),
                mailId:        r.querySelector(".c-mailId").value.trim(),
                linkedIn:      r.querySelector(".c-linkedIn").value.trim(),
                decisionMaker: r.querySelector(".c-decisionMaker").value,
                levelOfDM:     r.querySelector(".c-levelOfDM").value  // MODIFIED — CHANGES 1,2
            });
        });
        return out;
    }

    function resetAccountMasterAddModal() {
        ["am2_companyName","am2_location"].forEach(function(id){ document.getElementById(id).value=""; });
        document.getElementById("am2_vertical").value="";
        document.getElementById("am2_funnelStatus").value=""; // ADDED — CHANGE 1
        document.getElementById("am2_contactsContainer").innerHTML="";
        document.getElementById("am2-modal-msg").innerHTML="";
        addContactRow("am2_contactsContainer");
    }

    function loadAccountMasterData() {
        var container = document.getElementById("dynamic-content-container");
        if (activeTab==="accountmaster")
            container.innerHTML='<div style="padding:30px;text-align:center;color:#94a3b8;font-size:13px;">Loading...</div>';
        fetch(CONTEXT+"/getAccountMaster",{
            method:"POST", headers:{"Content-Type":"application/json"},
            body:JSON.stringify({userId:userId,uniqueId:uniqueId})
        })
        .then(function(r){return r.json();})
        .then(function(resp){
            accountMasterData = resp.data||[];
            if (activeTab==="accountmaster") renderAccountMasterTable(accountMasterData);
        })
        .catch(function(){
            if (activeTab==="accountmaster")
                document.getElementById("dynamic-content-container").innerHTML=
                    '<div class="empty-state"><i class="fa fa-triangle-exclamation"></i><p>Failed to load.</p></div>';
        });
    }

    function renderAccountMasterTable(list) {
        var c = document.getElementById("dynamic-content-container");
        if (!list||!list.length) { c.innerHTML='<div class="empty-state"><i class="fa fa-building"></i><p>No account master records found.</p></div>'; return; }
        var h = "<table class='table clean-table'><thead><tr><th>#</th><th>Company Name</th><th>Location</th><th>Vertical</th><th>Funnel Status</th><th>Contacts</th><th>Actions</th></tr></thead><tbody>";
        list.forEach(function(r,i){
            var contacts = r.contacts||[];
            var badge = contacts.length>0
                ? '<span class="chip" style="background:#f0fdf4;color:#15803d;">'+contacts.length+' contact'+(contacts.length>1?'s':'')+'</span>'
                : '<span style="color:var(--slate-400);font-size:12px;">None</span>';
            h += "<tr style='cursor:pointer;' onclick='openAccountMasterDetailModal("+r.id+")'><td>"+(i+1)+".</td><td><strong style='color:var(--green-primary);' title='"+escAttr(r.companyName||"")+"'>"+(r.companyName ? escapeHtml(r.companyName.length > 35 ? r.companyName.substring(0,35)+"..." : r.companyName) : "—")+"</strong></td>";
            var funnelChip = r.funnelStatus ? '<span class="chip" style="background:#f1f5f9;color:#334155;">'+r.funnelStatus+'</span>' : '<span style="color:var(--slate-400);">—</span>';
            // h += "<td>"+(r.location||"—")+"</td><td>"+(r.vertical||"—")+"</td><td>"+funnelChip+"</td><td>"+badge+"</td>";
            h += "<td><span title='"+escAttr(r.location||"")+"'>"+(r.location ? escapeHtml(r.location.length>20 ? r.location.substring(0,20)+"..." : r.location) : "—")+"</span></td><td>"+(r.vertical||"—")+"</td><td>"+funnelChip+"</td><td>"+badge+"</td>";
            h += "<td style='text-align:center;' onclick='event.stopPropagation()'>"
              + "<button class='btn btn-sm' style='margin-right:6px;background:#e8f7ee;color:#15803d;border:1px solid #bbf7d0;' onclick='event.stopPropagation();openMoveToProspectiveModal("+r.id+")'>Move To Prospective</button>"
              + "<button class='alert-menu-btn' data-id='"+r.id+"' onclick='event.stopPropagation();openActionMenu(this,"+r.id+")'>&#8942;</button></td></tr>";
        });
        h += "</tbody></table>";
        c.innerHTML = h;
    }

    window.saveAccountMaster = function () {
        var msg = document.getElementById("am2-modal-msg");
        var p = { userId:userId, uniqueId:uniqueId,
            companyName:document.getElementById("am2_companyName").value.trim(),
            location:document.getElementById("am2_location").value.trim(),
            vertical:document.getElementById("am2_vertical").value,
            funnelStatus:document.getElementById("am2_funnelStatus").value, // ADDED — CHANGE 1
            contacts:collectContacts("am2_contactsContainer") };
        if (!p.companyName) { msg.style.color="red"; msg.innerHTML="Company name is required."; return; }
        msg.style.color="#2563eb"; msg.innerHTML="Saving...";
        fetch(CONTEXT+"/saveAccountMaster",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(p)})
        .then(function(r){return r.json();})
        .then(function(resp){
            if(resp.status===200){ msg.style.color="green"; msg.innerHTML="Saved!";
                setTimeout(function(){ $("#accountMasterModal").modal("hide"); loadAccountMasterData(); },400); }
            else { msg.style.color="red"; msg.innerHTML=resp.message||"Error saving."; }
        }).catch(function(){ msg.style.color="red"; msg.innerHTML="Something went wrong."; });
    };

    function openAccountMasterEditModal(id) {
        var row = accountMasterData.find(function(r){ return r.id==id; });
        if (!row) { alert("Record not found. Reload."); return; }
        document.getElementById("edit_am2_id").value=row.id;
        document.getElementById("edit_am2_uniqueId").value=row.uniqueId||uniqueId;
        document.getElementById("edit_am2_companyName").value=row.companyName||"";
        document.getElementById("edit_am2_location").value=row.location||"";
        var verticalMap = {
        	    "Tech Park": "Tech Park/Campus",
        	    "Hotel": "Hotel/Food Chains",
        	    "Hospital": "Hospital"
        	};
        	var mappedVertical = verticalMap[row.vertical] || row.vertical || "";
        	document.getElementById("edit_am2_vertical").value = mappedVertical;
        // document.getElementById("edit_am2_vertical").value=row.vertical||"";
        document.getElementById("edit_am2_funnelStatus").value=row.funnelStatus||""; // ADDED — CHANGE 1
        var cont=document.getElementById("edit_am2_contactsContainer");
        cont.innerHTML="";
        var contacts=row.contacts||[];
        if(!contacts.length) addContactRow("edit_am2_contactsContainer");
        else contacts.forEach(function(cc){ addContactRow("edit_am2_contactsContainer",cc); });
        document.getElementById("edit-am2-modal-msg").innerHTML="";
        $("#editAccountMasterModal").modal("show");
    }

    window.updateAccountMaster = function () {
        var msg=document.getElementById("edit-am2-modal-msg");
        var p={ id:document.getElementById("edit_am2_id").value, uniqueId:document.getElementById("edit_am2_uniqueId").value||uniqueId,
            userId:userId, companyName:document.getElementById("edit_am2_companyName").value.trim(),
            location:document.getElementById("edit_am2_location").value.trim(),
            vertical:document.getElementById("edit_am2_vertical").value,
            funnelStatus:document.getElementById("edit_am2_funnelStatus").value, // ADDED — CHANGE 1
            contacts:collectContacts("edit_am2_contactsContainer") };
        if(!p.companyName){ msg.style.color="red"; msg.innerHTML="Company name is required."; return; }
        msg.style.color="#2563eb"; msg.innerHTML="Updating...";
        fetch(CONTEXT+"/editAccountMaster",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(p)})
        .then(function(r){return r.json();})
        .then(function(resp){
            if(resp.status===200){ msg.style.color="green"; msg.innerHTML="Updated!";
                setTimeout(function(){ $("#editAccountMasterModal").modal("hide"); loadAccountMasterData(); },400); }
            else { msg.style.color="red"; msg.innerHTML=resp.message||"Error updating."; }
        }).catch(function(){ msg.style.color="red"; msg.innerHTML="Something went wrong."; });
    };

    function deleteAccountMaster(id) {
        if(!confirm("Delete this account master? All contacts will also be deleted.")) return;
        fetch(CONTEXT+"/deleteAccountMaster?id="+id+"&uniqueId="+encodeURIComponent(uniqueId),{method:"POST"})
        .then(function(r){return r.json();})
        .then(function(resp){ if(resp.status===200) loadAccountMasterData(); else alert(resp.message||"Could not delete."); })
        .catch(function(){ alert("Something went wrong."); });
    }

