    // ADDED — CHANGES 2,6: auto-fill Level of DM and Designation when contact is selected
    window.tcAutoFillContact = function(selectEl, prefix) {
        var opt = selectEl.options[selectEl.selectedIndex];
        if (!opt || !opt.value) return;
        var levelOfDM    = opt.getAttribute("data-level-of-dm")    || "";
        var designation  = opt.getAttribute("data-designation")     || "";
        var decisionMaker = opt.getAttribute("data-decision-maker") || "";
        var lvlEl = document.getElementById(prefix + "_levelOfDM");
        var desEl = document.getElementById(prefix + "_designation");
        var dmEl  = document.getElementById(prefix + "_decisionMaker");
        if (lvlEl) lvlEl.value = levelOfDM;
        if (desEl) desEl.value = designation;
        if (dmEl)  dmEl.value  = decisionMaker;
        var contactIdEl = document.getElementById(prefix + "_accountContactId");
        if (contactIdEl) contactIdEl.value = opt.value || "";
    };

