    function renderTelecallingTable(list) {
        var c = document.getElementById("dynamic-content-container");
        if (!list||!list.length) { c.innerHTML='<div class="empty-state"><i class="fa fa-phone-slash"></i><p>No telecalling entries found for this date.</p></div>'; return; }
        var h = "<table class='table clean-table'><thead><tr>";
        ["#","Date","Company","Contact","Designation","Type of Call","DM","Level of DM","Status","Interest","Next Follow Up","Remarks","Actions"].forEach(function(hh){ h+="<th>"+hh+"</th>"; }); // MODIFIED — CHANGES 4,6,7
        h += "</tr></thead><tbody>";
        list.forEach(function(r,i){
            // h += "<tr><td>"+(i+1)+".</td>";
            h += "<tr style='cursor:pointer;' onclick='openTelecallingDetailModal("+r.id+")'><td>"+(i+1)+".</td>";
            h += "<td style='white-space:nowrap;'>"+(r.date||"—")+"</td>";
            // h += "<td><strong>"+(r.companyName||"—")+"</strong></td>";
            h += "<td><strong title='"+escAttr(r.companyName||"")+"'>"+(r.companyName ? escapeHtml(r.companyName.length > 40 ? r.companyName.substring(0,40)+"..." : r.companyName) : "—")+"</strong></td>";
            h += "<td>"+(r.contactPerson? escapeHtml(r.contactPerson) : "—")+"</td>";
            h += "<td style='color:#64748b;font-size:12px;'>"+(r.designation? escapeHtml(r.designation) : "—")+"</td>"; // ADDED — CHANGE 6
            h += "<td>"+(r.typeOfCall ? '<span class="chip" style="background:#e0f2fe;color:#0369a1;">'+r.typeOfCall+'</span>' : "—")+"</td>";
            h += "<td>"+chip(r.decisionMaker,"yn")+"</td>";
            h += "<td>"+(r.levelOfDM ? '<span class="chip" style="background:#f1f5f9;color:#334155;">'+r.levelOfDM+'</span>' : "—")+"</td>";
            h += "<td>"+(r.status ? '<span class="chip" style="background:#fef9c3;color:#854d0e;">'+r.status+'</span>' : "—")+"</td>";
            h += "<td>"+chip(r.interestCreated,"yn")+"</td>"; // ADDED — CHANGE 4
            h += "<td style='white-space:nowrap;'>"+(r.nextFollowUpDate||"—")+"</td>"; // ADDED — CHANGE 7
            //h += "<td style='max-width:200px;white-space:normal;font-size:12px;'>"+(r.remarks||"—")+"</td>";
            h += "<td><span title='"+escAttr(r.remarks||"")+"'>"+(r.remarks ? escapeHtml(r.remarks.length>30 ? r.remarks.substring(0,30)+"..." : r.remarks) : "—")+"</span></td>";
            // h += "<td style='text-align:center;'><button class='alert-menu-btn' data-id='"+r.id+"'>&#8942;</button></td></tr>";
            h += "<td style='text-align:center;'><button class='alert-menu-btn' data-id='"+r.id+"' onclick='event.stopPropagation();openActionMenu(this,"+r.id+")'>&#8942;</button></td></tr>";
        });
        h += "</tbody></table>";
        c.innerHTML = h;
    }
    
    window.tcHandleStatusChange = function() {
        var status = document.getElementById("tc_status").value;
        var icEl   = document.getElementById("tc_interestCreated");
        var icWrap = icEl.closest(".form-group");

        if (status === "Did not pick") {
            icWrap.style.display = "none";
            icEl.value = "";
        } else if (status === "Not interested") {
            icWrap.style.display = "";
            icEl.value = "No";
        } else if (status === "Meeting fixed" || status === "Demo scheduled") {
            icWrap.style.display = "";
            icEl.value = "Yes";
        } else if (status === "Answered") {
            icWrap.style.display = "";
            icEl.value = "";   // user must pick manually
        } else {
            icWrap.style.display = "";
            icEl.value = "";
        }
    };

    window.saveTelecalling = function () {
        var msg = document.getElementById("tc-modal-msg");
        var companyName = document.getElementById("tc_companyName").value.trim();
        var contactMeta = selectedContactMeta("tc_contactPerson");
        var accountMasterId = toLongOrNull(document.getElementById("tc_accountMasterId").value);
        // if (!companyName) { msg.style.color="red"; msg.innerHTML="Please select a company."; return; }
        if (!companyName) { msg.style.color="red"; msg.innerHTML="Please select a company."; return; }
		var status = document.getElementById("tc_status").value;
		var interestCreated = document.getElementById("tc_interestCreated").value;
		if (status === "Answered" && !interestCreated) { 
		    msg.style.color="red"; 
		    msg.innerHTML="Please select Interest Created for Answered calls."; 
		    return; 
		}
        var p = {
            userId:userId, uniqueId:uniqueId,
            date:           isoToDMY(document.getElementById("tc_date").value),
            companyName:    companyName,
            accountMasterId: accountMasterId,
            accountContactId: contactMeta.id,
            contactPerson:  contactMeta.name,
            typeOfCall:     document.getElementById("tc_typeOfCall").value,
            decisionMaker:  document.getElementById("tc_decisionMaker").value,
            levelOfDM:      document.getElementById("tc_levelOfDM").value,
            status:         document.getElementById("tc_status").value,
            remarks:        document.getElementById("tc_remarks").value.trim(),
            interestCreated: document.getElementById("tc_interestCreated").value,          // ADDED — CHANGE 4
            nextFollowUpDate: isoToDMY(document.getElementById("tc_nextFollowUpDate").value), // ADDED — CHANGE 7
            designation:     document.getElementById("tc_designation").value.trim()        // ADDED — CHANGE 6
        };
        msg.style.color="#2563eb"; msg.innerHTML="Saving...";
        fetch(CONTEXT+"/saveTelecalling",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(p)})
        .then(function(r){return r.json();})
        .then(function(resp){
            if(resp.status===200){ msg.style.color="green"; msg.innerHTML="Saved!";
                setTimeout(function(){ $("#telecallingModal").modal("hide"); loadTelecallingByDate(); },400); }
            else { msg.style.color="red"; msg.innerHTML=resp.message||"Error saving."; }
        }).catch(function(){ msg.style.color="red"; msg.innerHTML="Something went wrong."; });
    };

    function openTelecallingEditModal(id) {
        var row = telecallingData.find(function(r){ return r.id==id; });
        if (!row) { alert("Record not found. Reload."); return; }
        document.getElementById("edit_tc_id").value       = row.id;
        document.getElementById("edit_tc_uniqueId").value = row.uniqueId||uniqueId;
        document.getElementById("edit_tc_date").value     = dmyToISO(row.date);
        document.getElementById("edit_tc_typeOfCall").value    = row.typeOfCall||"";
        document.getElementById("edit_tc_decisionMaker").value  = row.decisionMaker||"";
        document.getElementById("edit_tc_levelOfDM").value      = row.levelOfDM||"";
        document.getElementById("edit_tc_status").value         = row.status||"";
        document.getElementById("edit_tc_remarks").value        = row.remarks||"";
        document.getElementById("edit_tc_interestCreated").value = row.interestCreated||"";
        document.getElementById("edit_tc_designation").value    = row.designation||"";     // ADDED — CHANGE 6
        document.getElementById("edit_tc_nextFollowUpDate").value = row.nextFollowUpDate ? dmyToISO(row.nextFollowUpDate) : ""; // ADDED — CHANGE 7
        document.getElementById("edit-tc-modal-msg").innerHTML = "";
        document.getElementById("edit_tc_accountMasterId").value = row.accountMasterId || "";
        document.getElementById("edit_tc_accountContactId").value = row.accountContactId || "";
        /* set company custom dropdown + contact person */
        csdSetValue("edit_tc_cmp", row.companyName||"", row.contactPerson||"", row.accountContactId, row.accountMasterId);
        document.getElementById("edit_tc_date").setAttribute("max", todayISO());
        $("#editTelecallingModal").modal("show");
    }

