	 window.liToggleConnectionStatus = function(activityType, wrapId) {
	     var wrap = document.getElementById(wrapId);
	     if (!wrap) return;
	     wrap.style.display = (activityType === "Connection Requests") ? "" : "none";
	     if (activityType !== "Connection Requests") {
	         var sel = wrap.querySelector("select");
	         if (sel) sel.value = "";
	     }
	 };

