	 function loadLinkedInByDate() {
		    var range = getDateRange();
		    if (!range) return;
		    var container = document.getElementById("dynamic-content-container");
		    container.innerHTML = '<div style="padding:30px;text-align:center;color:#94a3b8;font-size:13px;">Loading...</div>';
		    fetch(CONTEXT + "/getLinkedInByDate", {
		        method: "POST", headers: {"Content-Type": "application/json"},
		        body: JSON.stringify({userId: userId, uniqueId: uniqueId, fromDate: range.fromDate, toDate: range.toDate})
		    })
		    .then(function(r) { return r.json(); })
		    .then(function(resp) {
		        console.log("LI response:", resp);
		        linkedInData = resp.data || [];
		        renderLinkedInTable(linkedInData);
		    })
		    .catch(function(err) {
		        console.error("LI fetch error:", err);
		        container.innerHTML = '<div class="empty-state"><i class="fa fa-triangle-exclamation"></i><p>Failed to load data.</p></div>';
		    });
		}
	
