	 function renderLinkedInTable(list) {
	     var c = document.getElementById("dynamic-content-container");
	     if (!list || !list.length) {
	         c.innerHTML = '<div class="empty-state"><i class="fa-brands fa-linkedin" style="font-size:40px;margin-bottom:12px;display:block;opacity:.4;"></i><p>No LinkedIn activity entries found for this date.</p></div>';
	         return;
	     }
	     var h = "<table class='table clean-table'><thead><tr>";
	     ["#","Date","Company","Person Name","Activity Type","Connection Status","Msg Sent","Response","Interest","Follow Up","Next Steps","Remarks","Actions"]
	         .forEach(function(hh) { h += "<th>" + hh + "</th>"; });
	     h += "</tr></thead><tbody>";
	     list.forEach(function(r, i) {
	         // h += "<tr><td>" + (i + 1) + ".</td>";
	         h += "<tr style='cursor:pointer;' onclick='openLinkedInDetailModal("+r.id+")'><td>" + (i + 1) + ".</td>";
	         h += "<td style='white-space:nowrap;'>" + (r.date || "—") + "</td>";
	         // h += "<td><strong>" + (r.companyName || "—") + "</strong></td>";
	         h += "<td><strong title='"+escAttr(r.companyName||"")+"'>"+(r.companyName ? escapeHtml(r.companyName.length > 40 ? r.companyName.substring(0,40)+"..." : r.companyName) : "—")+"</strong></td>";
	         h += "<td>" + (r.personName ? escapeHtml(r.personName) : "—") + "</td>";
	         h += "<td>" + (r.activityType
	             ? '<span class="chip" style="background:#e0f2fe;color:#0369a1;">' + r.activityType + '</span>'
	             : "—") + "</td>";
	         h += "<td>" + (r.connectionStatus
	             ? '<span class="chip" style="background:#f1f5f9;color:#334155;">' + r.connectionStatus + '</span>'
	             : "—") + "</td>";
	         h += "<td>" + chip(r.messageSent,   "yn") + "</td>";
	         h += "<td>" + chip(r.responseReceived, "yn") + "</td>";
	         h += "<td>" + chip(r.interestCreated,  "yn") + "</td>";
	         h += "<td style='white-space:nowrap;'>" + (r.followUpDate || "—") + "</td>";
	         // h += "<td style='max-width:160px;white-space:normal;font-size:12px;'>" + (r.nextSteps || "—") + "</td>";
	         // h += "<td style='max-width:180px;white-space:normal;font-size:12px;'>" + (r.remarks   || "—") + "</td>";
	         h += "<td><span title='"+escAttr(r.nextSteps||"")+"'>"+(r.nextSteps ? escapeHtml(r.nextSteps.length>30 ? r.nextSteps.substring(0,30)+"..." : r.nextSteps) : "—")+"</span></td>";
h += "<td><span title='"+escAttr(r.remarks||"")+"'>"+(r.remarks ? escapeHtml(r.remarks.length>30 ? r.remarks.substring(0,30)+"..." : r.remarks) : "—")+"</span></td>";
	         // h += "<td style='text-align:center;'><button class='alert-menu-btn' data-id='" + r.id + "'>&#8942;</button></td></tr>";
	         h += "<td style='text-align:center;'><button class='alert-menu-btn' data-id='" + r.id + "' onclick='event.stopPropagation();openActionMenu(this,"+r.id+")'>&#8942;</button></td></tr>";
	     });
	     h += "</tbody></table>";
	     c.innerHTML = h;
	 }
	 
	 window.saveLinkedIn = function() {
		    var msg = document.getElementById("li-modal-msg");
		    var companyName = document.getElementById("li_companyName").value.trim();
		    var contactMeta = selectedContactMeta("li_personName");
		    var accountMasterId = toLongOrNull(document.getElementById("li_accountMasterId").value);

		    if (!companyName) {
		        msg.style.color = "red";
		        msg.innerHTML = "Please select a company.";
		        return;
		    }

		    var selectedDate = document.getElementById("li_date").value;

		    var p = {
		        userId: userId,
		        uniqueId: uniqueId,

		        date: isoToDMY(selectedDate),   // ✅ FIXED
		        savingDate: isoToDMY(selectedDate), // optional (same now)

		        companyName: companyName,
		        accountMasterId: accountMasterId,
		        accountContactId: contactMeta.id,
		        personName: contactMeta.name,
		        activityType: document.getElementById("li_activityType").value,
		        connectionStatus: document.getElementById("li_connectionStatus").value,
		        messageSent: document.getElementById("li_messageSent").value,
		        responseReceived: document.getElementById("li_responseReceived").value,
		        interestCreated: document.getElementById("li_interestCreated").value,
		        followUpDate: isoToDMY(document.getElementById("li_followUpDate").value),
		        nextSteps: document.getElementById("li_nextSteps").value.trim(),
		        remarks: document.getElementById("li_remarks").value.trim()
		    };

		    msg.style.color = "#2563eb";
		    msg.innerHTML = "Saving...";

		    fetch(CONTEXT + "/saveLinkedIn", {
		        method: "POST",
		        headers: {"Content-Type": "application/json"},
		        body: JSON.stringify(p)
		    })
		    .then(function(r) { return r.json(); })
		    .then(function(resp) {
		        if (resp.status === 200) {
		            msg.style.color = "green";
		            msg.innerHTML = "Saved!";
		            setTimeout(function() {
		                $("#linkedInModal").modal("hide");
		                loadLinkedInByDate();
		            }, 400);
		        } else {
		            msg.style.color = "red";
		            msg.innerHTML = resp.message || "Error saving.";
		        }
		    })
		    .catch(function() {
		        msg.style.color = "red";
		        msg.innerHTML = "Something went wrong.";
		    });
		};
	
