	 function vtcCloseAll(exceptKey) {
	     document.querySelectorAll(".custom-select-panel.open").forEach(function(panel) {
	         var pid = panel.id;
	         if (!exceptKey || pid !== exceptKey + "_panel") {
	             panel.classList.remove("open");
	             var t = document.getElementById(pid.replace("_panel","_trigger"));
	             if (t) t.classList.remove("open");
	         }
	     });
	 }
	 window.vtcToggle = function(key) {
	     var panel   = document.getElementById(key + "_panel");
	     var trigger = document.getElementById(key + "_trigger");
	     var isOpen  = panel.classList.contains("open");
	     vtcCloseAll(key);
	     if (!isOpen) {
	         vtcBuild(key);
	         document.getElementById(key + "_search").value = "";
	         vtcFilter(key);
	         panel.classList.add("open");
	         trigger.classList.add("open");
	         setTimeout(function() { document.getElementById(key + "_search").focus(); }, 50);
	     }
	 };
	 function vtcBuild(key) {
	     var list = document.getElementById(key + "_list");
	     var hiddenId = key.replace("_vtc","") + "_vertical";
	     var currentVal = document.getElementById(hiddenId) ? document.getElementById(hiddenId).value : "";
	     list.innerHTML = "";
	     VERTICALS.forEach(function(v) {
	         var item = document.createElement("div");
	         item.className = "custom-select-item" + (v === currentVal ? " selected" : "");
	         item.textContent = v;
	         item.setAttribute("data-value", v);
	         item.onmousedown = function(e) { e.preventDefault(); vtcSelect(key, v); };
	         list.appendChild(item);
	     });
	 }
	 window.vtcFilter = function(key) {
	     var term  = document.getElementById(key + "_search").value.toLowerCase().trim();
	     var items = document.getElementById(key + "_list").querySelectorAll(".custom-select-item:not(.no-results)");
	     var vis   = 0;
	     items.forEach(function(item) {
	         var match = !term || item.textContent.toLowerCase().includes(term);
	         item.style.display = match ? "" : "none";
	         if (match) vis++;
	     });
	     var noRes = document.getElementById(key + "_list").querySelector(".no-results");
	     if (vis === 0) {
	         if (!noRes) {
	             var d = document.createElement("div");
	             d.className = "custom-select-item no-results";
	             d.textContent = "No matching vertical";
	             document.getElementById(key + "_list").appendChild(d);
	         } else { noRes.style.display = ""; }
	     } else { if (noRes) noRes.style.display = "none"; }
	 };
	 function vtcSelect(key, value) {
	     var hiddenId = key.replace("_vtc","") + "_vertical";
	     document.getElementById(hiddenId).value = value;
	     var label = document.getElementById(key + "_label");
	     label.textContent = value;
	     label.classList.remove("placeholder");
	     document.getElementById(key + "_panel").classList.remove("open");
	     document.getElementById(key + "_trigger").classList.remove("open");
	 }
	 function vtcSetValue(key, value) {
	     var hiddenId = key.replace("_vtc","") + "_vertical";
	     document.getElementById(hiddenId).value = value || "";
	     var label = document.getElementById(key + "_label");
	     if (value) {
	         label.textContent = value;
	         label.classList.remove("placeholder");
	     } else {
	         label.textContent = "Select Vertical";
	         label.className = "custom-select-trigger-text placeholder";
	     }
	 }
	
