	 var _prsContacts = {};
	
	 function prsCloseAll(exceptKey) {
	     document.querySelectorAll(".custom-select-panel.open").forEach(function(panel) {
	         var pid = panel.id;
	         if (!exceptKey || pid !== exceptKey + "_panel") {
	             panel.classList.remove("open");
	             var t = document.getElementById(pid.replace("_panel","_trigger"));
	             if (t) t.classList.remove("open");
	         }
	     });
	 }
	 window.prsToggle = function(key) {
	     var panel   = document.getElementById(key + "_panel");
	     var trigger = document.getElementById(key + "_trigger");
	     var isOpen  = panel.classList.contains("open");
	     prsCloseAll(key);
	     if (!isOpen) {
	         prsBuild(key);
	         document.getElementById(key + "_search").value = "";
	         prsFilter(key);
	         panel.classList.add("open");
	         trigger.classList.add("open");
	         setTimeout(function() { document.getElementById(key + "_search").focus(); }, 50);
	     }
	 };
	 function prsBuild(key) {
	     var list     = document.getElementById(key + "_list");
	     var prefix   = key.replace("_prs","");
	     var contacts = _prsContacts[prefix] || [];
	     var hiddenId = prefix + "_spocName";
	     var currentVal = document.getElementById(hiddenId) ? document.getElementById(hiddenId).value : "";
	     var currentContactId = document.getElementById(prefix + "_accountContactId")
	         ? document.getElementById(prefix + "_accountContactId").value
	         : "";
	     list.innerHTML = "";
	     if (!contacts.length) {
	         var d = document.createElement("div");
	         d.className = "custom-select-item no-results";
	         d.textContent = "Select a company first";
	         list.appendChild(d);
	         return;
	     }
	     contacts.forEach(function(c) {
	         var item = document.createElement("div");
	         item.className = "custom-select-item" +
	             (((currentContactId && String(c.id) === String(currentContactId)) || c.personName === currentVal) ? " selected" : "");
	         // item.textContent = c.personName + (c.designation ? " – " + c.designation : "");
	         item.textContent = c.personName + (c.mailId ? " – " + c.mailId : "");
	         item.setAttribute("data-value", c.personName);
	         item.onmousedown = function(e) { e.preventDefault(); prsSelect(key, c); };
	         list.appendChild(item);
	     });
	 }
	 window.prsFilter = function(key) {
	     var term  = document.getElementById(key + "_search").value.toLowerCase().trim();
	     var items = document.getElementById(key + "_list").querySelectorAll(".custom-select-item:not(.no-results)");
	     var vis   = 0;
	     items.forEach(function(item) {
	         var match = !term || item.textContent.toLowerCase().includes(term);
	         item.style.display = match ? "" : "none";
	         if (match) vis++;
	     });
	     var noRes = document.getElementById(key + "_list").querySelector(".no-results");
	     if (vis === 0) {
	         if (!noRes) {
	             var d = document.createElement("div");
	             d.className = "custom-select-item no-results";
	             d.textContent = "No matching person";
	             document.getElementById(key + "_list").appendChild(d);
	         } else { noRes.style.display = ""; }
	     } else { if (noRes) noRes.style.display = "none"; }
	 };
	 
	 function prsSelect(key, contact) {
		    var prefix = key.replace("_prs","");

		    // fill hidden spocName
		    var spocEl = document.getElementById(prefix + "_spocName");
		    if (spocEl) spocEl.value = contact.personName || "";
		    var contactIdEl = document.getElementById(prefix + "_accountContactId");
		    if (contactIdEl) contactIdEl.value = contact.id || "";

		    // update trigger label
		    var label = document.getElementById(key + "_label");
		    if (label) {
		        // label.textContent = contact.personName + (contact.designation ? " – " + contact.designation : "");
		        label.textContent = contact.personName + (contact.mailId ? " – " + contact.mailId : "");
		        label.classList.remove("placeholder");
		    }

		    // close panel
		    document.getElementById(key + "_panel").classList.remove("open");
		    document.getElementById(key + "_trigger").classList.remove("open");

		    // ── auto-fill SPOC detail fields ──
		    // prefix is "lid" or "edit_lid"
		    var desEl  = document.getElementById(prefix + "_designation");
		    var mailEl = document.getElementById(prefix + "_mail");
		    var mobEl  = document.getElementById(prefix + "_mobile");
		    var liEl   = document.getElementById(prefix + "_linkedInURL");

		    if (desEl)  desEl.value  = contact.designation   || "";
		    if (mailEl) mailEl.value = contact.mailId         || "";
		    if (mobEl)  mobEl.value  = contact.contactNumber  || "";
		    if (liEl)   liEl.value   = contact.linkedIn       || "";
		}
	 
