	 function prsSetValue(key, personName, contacts, accountContactId) {
	     var prefix = key.replace("_prs","");
	     _prsContacts[prefix] = contacts || [];
	     var label = document.getElementById(key + "_label");
	     var contactIdEl = document.getElementById(prefix + "_accountContactId");
	     if (personName) {
	         var contact = (contacts || []).find(function(c) {
	             if (accountContactId && String(c.id) === String(accountContactId)) return true;
	             return c.personName === personName;
	         });
	         document.getElementById(prefix + "_spocName").value = personName;
	         if (contactIdEl) contactIdEl.value = contact ? (contact.id || "") : (accountContactId || "");
	         label.textContent = contact
		         ? personName + (contact.mailId ? " – " + contact.mailId : "")
		         : personName;
	         label.classList.remove("placeholder");
	     } else {
	         document.getElementById(prefix + "_spocName").value = "";
	         if (contactIdEl) contactIdEl.value = "";
	         label.textContent = "— Select company first —";
	         label.className = "custom-select-trigger-text placeholder";
	     }
	 }
	
