	 function lidOnCompanySelect(master) {
	     var locEl = document.getElementById("lid_location");
	     if (locEl) locEl.value = master.location || "";
	     vtcSetValue("lid_vtc", master.vertical || "");
	     _prsContacts["lid"] = master.contacts || [];
	     prsSetValue("lid_prs", "", master.contacts || [], null);
	     ["lid_designation","lid_mail","lid_mobile","lid_linkedInURL"].forEach(function(id) {
	         var el = document.getElementById(id); if (el) el.value = "";
	     });
	 }
	 function editLidOnCompanySelect(master) {
	     var locEl = document.getElementById("edit_lid_location");
	     if (locEl) locEl.value = master.location || "";
	     vtcSetValue("edit_lid_vtc", master.vertical || "");
	     _prsContacts["edit_lid"] = master.contacts || [];
	 }
	
