	 function resetLeadIdentificationAddModal() {
	     document.getElementById("lid_companyName").value = "";
	     document.getElementById("lid_accountMasterId").value = "";
	     document.getElementById("lid_accountContactId").value = "";
	     var lbl = document.getElementById("lid_cmp_label");
	     lbl.textContent = "Select Company";
	     lbl.className = "custom-select-trigger-text placeholder";
	     document.getElementById("lid_cmp_trigger").classList.remove("open");
	     document.getElementById("lid_cmp_panel").classList.remove("open");
	     vtcSetValue("lid_vtc", "");
	     _prsContacts["lid"] = [];
	     prsSetValue("lid_prs", "", [], null);
	     ["lid_location","lid_buildingSize","lid_noOfTowers","lid_noOfAdditionalLocations",
	      "lid_designation","lid_mail","lid_mobile","lid_linkedInURL",
	      "lid_nextSteps","lid_remarks","lid_nextFollowUpDate"].forEach(function(id) {
	         var el = document.getElementById(id); if (el) el.value = "";
	     });
	     ["lid_headQuartered","lid_existingProcess","lid_techUsed","lid_meetingScheduled"].forEach(function(id) {
	         document.getElementById(id).value = "";
	     });
	     document.getElementById("lid_date").value = todayISO();
	     document.getElementById("lid-modal-msg").innerHTML = "";
	 }
	 
	 function loadLeadIdentificationByDate() {
		    var range = getDateRange();
		    if (!range) return;
		    var c = document.getElementById("dynamic-content-container");
		    c.innerHTML = '<div style="padding:30px;text-align:center;color:#94a3b8;font-size:13px;">Loading...</div>';
		    fetch(CONTEXT + "/getLeadIdentificationByDate", {
		        method: "POST", headers: {"Content-Type": "application/json"},
		        body: JSON.stringify({userId: userId, uniqueId: uniqueId, fromDate: range.fromDate, toDate: range.toDate})
		    })
		    .then(function(r) { return r.json(); })
		    .then(function(resp) {
		        console.log("LID response:", resp);
		        leadIdentificationData = resp.data || [];
		        renderLeadIdentificationTable(leadIdentificationData);
		    })
		    .catch(function(err) {
		        console.error("LID fetch error:", err);
		        c.innerHTML = '<div class="empty-state"><i class="fa fa-triangle-exclamation"></i><p>Failed to load data.</p></div>';
		    });
		}
	
	 function renderLeadIdentificationTable(list) {
	     var c = document.getElementById("dynamic-content-container");
	     if (!list || !list.length) {
	         c.innerHTML = '<div class="empty-state"><i class="fa fa-magnifying-glass-chart" style="font-size:40px;margin-bottom:12px;display:block;opacity:.4;"></i><p>No lead identification entries found for this date.</p></div>';
	         return;
	     }
	     var cols = ["#","Date","Company","Location","Vertical","Bldg Size(.sft)","Towers","Add.Locs","Head Quartered",
	                 "Person","Designation","Email","Mobile","LinkedIn","Process","Tech","Meeting?",
	                 "Next Follow Up","Next Steps","Remarks","Actions"];
	     var h = "<div style='overflow-x:auto;'><table class='table clean-table'><thead><tr>";
	     cols.forEach(function(hh) { h += "<th>" + hh + "</th>"; });
	     h += "</tr></thead><tbody>";
	     list.forEach(function(r, i) {
	         function yn(v) {
	             return v ? (v==="Yes" ? '<span class="chip chip-yes">Yes</span>' : '<span class="chip chip-no">No</span>')
	                      : '<span class="chip" style="background:#f1f5f9;color:#94a3b8;">—</span>';
	         }
	         h += "<tr style='cursor:pointer;' onclick='openLeadIdentificationDetailModal("+r.id+")'>";
	         h += "<td>" + (i+1) + ".</td>";
	         // h += "<tr>";
	         // h += "<td>" + (i+1) + ".</td>";
	         h += "<td style='white-space:nowrap;'>" + dash(r.date) + "</td>";
	         h += "<td><strong>" + dash(escapeHtml(r.companyName)) + "</strong></td>";
	         h += "<td>" + dash(escapeHtml(r.location)) + "</td>";
	         h += "<td>" + dash(r.vertical) + "</td>";
	         h += "<td>" + dash(r.buildingSize) + "</td>";
	         h += "<td>" + dash(r.noOfTowers) + "</td>";
	         h += "<td>" + dash(r.noOfAdditionalLocations) + "</td>";
	         // h += "<td>" + yn(r.headQuartered) + "</td>";
	         h += "<td>" + dash(escapeHtml(r.headQuartered)) + "</td>";
	         h += "<td>" + dash(escapeHtml(r.spocName)) + "</td>";
	         h += "<td>" + dash(escapeHtml(r.designation)) + "</td>";
	         h += "<td>" + dash(escapeHtml(r.mail)) + "</td>";
	         h += "<td>" + dash(escapeHtml(r.mobile)) + "</td>";
	         h += "<td>" + (safeHref(r.linkedInURL) ? '<a href="'+safeHref(r.linkedInURL)+'" target="_blank" style="color:var(--green-primary);">View</a>' : "—") + "</td>";
	         h += "<td>" + dash(r.existingProcess) + "</td>";
	         h += "<td>" + dash(escapeHtml(r.techUsed)) + "</td>";
	         h += "<td>" + yn(r.meetingScheduled) + "</td>";
	         h += "<td style='white-space:nowrap;'>" + dash(r.nextFollowUpDate) + "</td>";
	         // h += "<td style='max-width:160px;white-space:normal;font-size:12px;'>" + dash(r.nextSteps) + "</td>";
	         // h += "<td style='max-width:180px;white-space:normal;font-size:12px;'>" + dash(r.remarks) + "</td>";
	         h += "<td><span title='"+escAttr(r.nextSteps||"")+"'>"+(r.nextSteps ? escapeHtml(r.nextSteps.length>30 ? r.nextSteps.substring(0,30)+"..." : r.nextSteps) : "—")+"</span></td>";
h += "<td><span title='"+escAttr(r.remarks||"")+"'>"+(r.remarks ? escapeHtml(r.remarks.length>30 ? r.remarks.substring(0,30)+"..." : r.remarks) : "—")+"</span></td>";
	         // h += "<td style='text-align:center;'><button class='alert-menu-btn' data-id='" + r.id + "'>&#8942;</button></td>";
	         h += "<td style='text-align:center;'><button class='alert-menu-btn' data-id='" + r.id + "' onclick='event.stopPropagation();openActionMenu(this,"+r.id+")'>&#8942;</button></td>";
	         h += "</tr>";
	     });
	     h += "</tbody></table></div>";
	     c.innerHTML = h;
	 }
	
	 window.saveLeadIdentification = function() {
	     var msg = document.getElementById("lid-modal-msg");
	     var companyName = document.getElementById("lid_companyName").value.trim();
	     var accountMasterId = toLongOrNull(document.getElementById("lid_accountMasterId").value);
	     var accountContactId = toLongOrNull(document.getElementById("lid_accountContactId").value);
	     if (!companyName) { msg.style.color = "red"; msg.innerHTML = "Please select a company."; return; }
	     var p = {
	         userId: userId, uniqueId: uniqueId,
	         date:                   isoToDMY(document.getElementById("lid_date").value),
	         companyName:            companyName,
	         accountMasterId:        accountMasterId,
	         accountContactId:       accountContactId,
	         location:               document.getElementById("lid_location").value.trim(),
	         vertical:               document.getElementById("lid_vertical").value,
	         buildingSize:           document.getElementById("lid_buildingSize").value.trim(),
	         noOfTowers:             document.getElementById("lid_noOfTowers").value.trim(),
	         noOfAdditionalLocations:document.getElementById("lid_noOfAdditionalLocations").value.trim(),
	         headQuartered:          document.getElementById("lid_headQuartered").value,
	         spocName:               document.getElementById("lid_spocName").value.trim(),
	         designation:            document.getElementById("lid_designation").value.trim(),
	         mail:                   document.getElementById("lid_mail").value.trim(),
	         mobile:                 document.getElementById("lid_mobile").value.trim(),
	         linkedInURL:            document.getElementById("lid_linkedInURL").value.trim(),
	         existingProcess:        document.getElementById("lid_existingProcess").value,
	         techUsed:               document.getElementById("lid_techUsed").value,
	         meetingScheduled:       document.getElementById("lid_meetingScheduled").value,
	         nextFollowUpDate:       isoToDMY(document.getElementById("lid_nextFollowUpDate").value),
	         nextSteps:              document.getElementById("lid_nextSteps").value.trim(),
	         remarks:                document.getElementById("lid_remarks").value.trim()
	     };
	     msg.style.color = "#2563eb"; msg.innerHTML = "Saving...";
	     fetch(CONTEXT + "/saveLeadIdentification", {
	         method: "POST", headers: {"Content-Type": "application/json"}, body: JSON.stringify(p)
	     })
	     .then(function(r) { return r.json(); })
	     .then(function(resp) {
	         if (resp.status === 200) {
	             msg.style.color = "green"; msg.innerHTML = "Saved!";
	             setTimeout(function() { $("#leadIdentificationModal").modal("hide"); loadLeadIdentificationByDate(); }, 400);
	         } else { msg.style.color = "red"; msg.innerHTML = resp.message || "Error saving."; }
	     }).catch(function() { msg.style.color = "red"; msg.innerHTML = "Something went wrong."; });
	 };
	 
