	 function openLeadIdentificationEditModal(id) {
	     var row = leadIdentificationData.find(function(r) { return r.id == id; });
	     if (!row) { alert("Record not found. Reload."); return; }
	     document.getElementById("edit_lid_id").value       = row.id;
	     document.getElementById("edit_lid_uniqueId").value = row.uniqueId || uniqueId;
	     document.getElementById("edit_lid_date").value     = dmyToISO(row.date);
	     ["location","buildingSize","noOfTowers","noOfAdditionalLocations",
	      "designation","mail","mobile","linkedInURL","nextSteps","remarks"].forEach(function(f) {
	         var el = document.getElementById("edit_lid_" + f); if (el) el.value = row[f] || "";
	     });
	     ["headQuartered","existingProcess","techUsed","meetingScheduled"].forEach(function(f) {
	         document.getElementById("edit_lid_" + f).value = row[f] || "";
	     });
	     document.getElementById("edit_lid_nextFollowUpDate").value = dmyToISO(row.nextFollowUpDate);
	     /* company dropdown */
	     var master = accountMasterData.find(function(m) { return m.companyName === row.companyName; });
	     var contacts = master ? (master.contacts || []) : [];
	     _prsContacts["edit_lid"] = contacts;
	     document.getElementById("edit_lid_companyName").value = row.companyName || "";
	     document.getElementById("edit_lid_accountMasterId").value = row.accountMasterId || (master ? master.id : "");
	     document.getElementById("edit_lid_accountContactId").value = row.accountContactId || "";
	     var cmpLabel = document.getElementById("edit_lid_cmp_label");
	     if (row.companyName) {
	         cmpLabel.textContent = master ? companyLabel(master) : row.companyName;
	         cmpLabel.classList.remove("placeholder");
	     } else {
	         cmpLabel.textContent = "Select Company";
	         cmpLabel.className = "custom-select-trigger-text placeholder";
	     }
	     /* vertical + person dropdowns */
	     // vtcSetValue("edit_lid_vtc", row.vertical || "");
	     var verticalMap = {
			    "Tech Park": "Tech Park/Campus",
			    "Hotel": "Hotel/Food Chains",
			    "Hospital": "Hospital"
			};
			vtcSetValue("edit_lid_vtc", verticalMap[row.vertical] || row.vertical || "");
	     prsSetValue("edit_lid_prs", row.spocName || "", contacts, row.accountContactId);
	     document.getElementById("edit-lid-modal-msg").innerHTML = "";
	     document.getElementById("edit_lid_date").setAttribute("max", todayISO());
	     $("#editLeadIdentificationModal").modal("show");
	 }
	
